function dl(content,name,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();}
function csvEsc(s){s=(s==null?'':''+s);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;}
function esc(s){return (s==null?'':(''+s)).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function parseCSV(text){const rows=[];let i=0,f='',row=[],q=false;while(i<text.length){const c=text[i];if(q){if(c=='"'){if(text[i+1]=='"'){f+='"';i++;}else q=false;}else f+=c;}else{if(c=='"')q=true;else if(c==','){row.push(f);f='';}else if(c=='\n'||c=='\r'){if(c=='\r'&&text[i+1]=='\n')i++;if(f!==''||row.length){row.push(f);rows.push(row);row=[];f='';}}else f+=c;}i++;}if(f!==''||row.length){row.push(f);rows.push(row);}return rows;}
function read(k,d){try{const v=JSON.parse(localStorage.getItem(k)||'null');return v==null?d:v;}catch(e){return d;}}
function store(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch(e){}}
function mdToHtml(md){if(!md)return'';let h=esc(md);h=h.replace(/^### (.*)$/gm,'<h4>$1</h4>').replace(/^## (.*)$/gm,'<h3 style="font-size:15px">$1</h3>').replace(/^# (.*)$/gm,'<h3 style="font-size:16px">$1</h3>');h=h.replace(/\*\*([^*]+)\*\*/g,'<b>$1</b>').replace(/\*([^*]+)\*/g,'<i>$1</i>').replace(/`([^`]+)`/g,'<span class="mono">$1</span>');h=h.replace(/^\s*[-*] (.*)$/gm,'<li>$1</li>');h=h.replace(/(<li>[\s\S]*?<\/li>)/g,'<ul style="margin:4px 0 8px 18px">$1</ul>');h=h.replace(/\n{2,}/g,'<br><br>').replace(/\n/g,'<br>');return h;}
const ROLES={agent:{label:'Agent',em:'🎧',home:'agentdash',perms:['home','live','agentconvo','kb','agentdash','library'],desc:'Handle calls, get live AI script guidance, view coaching notes, and track quality.'},evaluator:{label:'Evaluator',em:'✅',home:'evaldash',perms:['home','agentconvo','batch','kb','leader','team','library','evaldash','insights'],desc:'Review & score interactions, auto gap analysis, send evals to Supervisor, recommend enrollment, view insights.'},supervisor:{label:'Supervisor',em:'🧑‍✈️',home:'supervisordash',perms:['home','supervisordash','supqueue','sup','live','agentconvo','library','team','leader','frauddash','kb','insights'],desc:'Receive QA evals, add feedback, notify QA, coach agents, monitor teams, and read insights.'},trainer:{label:'Trainer',em:'🧑‍🏫',home:'trainerdash',perms:['home','trainerdash','kb','library','leader','insights'],desc:'Manage training topics (Markdown), receive enrollment recommendations, and coach agents.'},fraud:{label:'Fraud Analyst',em:'🛡️',home:'frauddash',perms:['home','fraud','sup','library','frauddash','kb'],desc:'Monitor fraud signals, manage rules, review high-risk interactions.'},admin:{label:'Admin',em:'👑',home:'admindash',perms:['home','live','agentconvo','batch','agentdb','team','kb','fraud','sup','leader','library','settings','access','audit','admindash','evaldash','frauddash','agentdash','supervisordash','supqueue','trainerdash','insights'],desc:'Full access to every dashboard, config, users & audit.'}};
const PERM_LABELS={home:'🏠 Home',live:'🎙️ Live Voice',agentconvo:'🎬 Agent Convo',batch:'📤 Batch',agentdb:'👥 Agent DB',team:'🏢 Team',kb:'📚 KB',fraud:'🛡️ Fraud',sup:'🎧 Sup Live',leader:'🏆 Leaderboard',library:'📁 Interactions',settings:'⚙️ Setup',access:'🔐 Access',audit:'🧾 Audit',admindash:'👑 Admin',evaldash:'✅ Evaluator',frauddash:'🛡️ Fraud Dash',agentdash:'🎧 Agent',supervisordash:'🧑‍✈️ Supervisor',supqueue:'📥 Eval Inbox',trainerdash:'🧑‍🏫 Trainer',insights:'📈 Insights'};
const NAV_ITEMS=[['home','🏠 Home'],['agentdash','🎧 My Dashboard'],['evaldash','✅ Evaluator'],['supervisordash','🧑‍✈️ Supervisor'],['supqueue','📥 Eval Inbox'],['trainerdash','🧑‍🏫 Trainer'],['frauddash','🛡️ Fraud Analyst'],['admindash','👑 Admin'],['insights','📈 Insights'],['live','🎙️ Live Voice'],['agentconvo','🎬 Live Agent Convo'],['batch','📤 Batch Upload'],['agentdb','👥 Agent Database'],['team','🏢 Team Dashboard'],['kb','📚 Knowledge Base'],['fraud','🛡️ Fraud'],['sup','🎧 Supervisor Live'],['leader','🏆 Leaderboard'],['library','📁 Interactions'],['access','🔐 Access Mgmt'],['audit','🧾 Audit Log'],['settings','⚙️ Setup']];
function defaultUsers(){return [{user:'admin',name:'System Administrator',pass:'admin123',role:'admin',emp:'',status:'active'},{user:'evaluator',name:'Quality Evaluator',pass:'eval123',role:'evaluator',emp:'',status:'active'},{user:'supervisor',name:'Team Supervisor',pass:'super123',role:'supervisor',emp:'',status:'active'},{user:'trainer',name:'Training Officer',pass:'train123',role:'trainer',emp:'',status:'active'},{user:'fraud',name:'Fraud Analyst',pass:'fraud123',role:'fraud',emp:'',status:'active'},{user:'agent',name:'Juan Dela Cruz',pass:'agent123',role:'agent',emp:'EMP-1001',status:'active'}];}
function loadUsers(){let u=null;try{u=JSON.parse(localStorage.getItem('ft_users')||'null');}catch(e){}if(!u||!u.length){u=defaultUsers();store('ft_users',u);return u;}let ch=false;defaultUsers().forEach(d=>{if(!u.some(x=>x.user===d.user)){u.push(d);ch=true;}});if(ch)store('ft_users',u);return u;}
function saveUsers(a){store('ft_users',a);}
let currentUser=null;
function fillLogin(u,p){document.getElementById('loginUser').value=u;document.getElementById('loginPass').value=p;}
function doLogin(){const u=document.getElementById('loginUser').value.trim().toLowerCase();const p=document.getElementById('loginPass').value;const err=document.getElementById('loginErr');const m=loadUsers().find(x=>x.user.toLowerCase()===u);if(!m||m.pass!==p){err.textContent='❌ Invalid username or password.';return;}if(m.status!=='active'){err.textContent='⛔ Account disabled.';return;}currentUser=m;store('ft_session',{user:m.user});err.textContent='';document.getElementById('loginOverlay').classList.add('hidden');document.getElementById('app').classList.remove('hidden');logAudit('Signed in',m.user+' ('+m.role+')','auth');applyRBAC();}
function logout(){try{if(currentUser)logAudit('Signed out',currentUser.user,'auth');}catch(e){}try{if(typeof callActive!=='undefined'&&callActive)endCall();}catch(e){}try{if(typeof acActive!=='undefined'&&acActive){acActive=false;acStopRec();}}catch(e){}try{stopCamera&&stopCamera();}catch(e){}try{stopSysAudio&&stopSysAudio();}catch(e){}try{stopMixRecording&&stopMixRecording();}catch(e){}try{stopSpeaking&&stopSpeaking();}catch(e){}try{ftStopMeter&&ftStopMeter();}catch(e){}currentUser=null;try{localStorage.removeItem('ft_session');}catch(e){}const app=document.getElementById('app');if(app)app.classList.add('hidden');const ov=document.getElementById('loginOverlay');if(ov)ov.classList.remove('hidden');const lp=document.getElementById('loginPass');if(lp)lp.value='';const lu=document.getElementById('loginUser');if(lu){lu.value='';try{lu.focus();}catch(e){}}return false;}
window.logout=logout;
function quickSwap(user){const m=loadUsers().find(x=>x.user===user);if(!m||m.status!=='active')return;try{if(typeof callActive!=='undefined'&&callActive)endCall();}catch(e){}try{stopCamera&&stopCamera();}catch(e){}currentUser=m;store('ft_session',{user:m.user});logAudit('Switched user','→ '+m.user+' ('+m.role+')','auth');applyRBAC();}
window.quickSwap=quickSwap;
function restoreSession(){try{const s=read('ft_session',null);if(s){const m=loadUsers().find(x=>x.user===s.user);if(m&&m.status==='active'){currentUser=m;document.getElementById('loginOverlay').classList.add('hidden');document.getElementById('app').classList.remove('hidden');applyRBAC();return;}}}catch(e){}}
function can(view){return currentUser&&ROLES[currentUser.role].perms.includes(view);}
function fillSwitchUser(){const sw=document.getElementById('ftSwitchUser');if(!sw)return;const us=loadUsers().filter(u=>u.status==='active');sw.innerHTML='<option value="">🔀 Switch user…</option>'+us.map(u=>'<option value="'+u.user+'"'+((currentUser&&currentUser.user===u.user)?' selected':'')+'>'+ROLES[u.role].em+' '+esc(u.name)+' ('+u.role+')</option>').join('');}
function applyRBAC(){const r=ROLES[currentUser.role];document.getElementById('userName').textContent=currentUser.name;document.getElementById('userRole').textContent=r.em+' '+r.label;const nav=document.getElementById('navBar');nav.innerHTML='';NAV_ITEMS.forEach(([id,label])=>{if(r.perms.includes(id)){const b=document.createElement('button');b.className='tab';b.dataset.view=id;b.innerHTML=label+(id==='supqueue'?' <span class="pill-count hidden" id="supInboxCount" style="background:var(--magenta)">0</span>':'')+(id==='audit'?' <span class="pill-count hidden" id="auditTabCount" style="background:var(--teal)">0</span>':'');b.onclick=()=>showView(id);nav.appendChild(b);}});const lb=document.getElementById('logoutBtn');if(lb)lb.onclick=logout;buildHome();showView(r.home);fillSwitchUser();refreshBell();refreshDMBadge();const n=loadAudit().length;const badge=document.getElementById('auditTabCount');if(badge&&n){badge.textContent=n;badge.classList.remove('hidden');}}
function showView(id){if(!can(id))id=ROLES[currentUser.role].home;document.querySelectorAll('#navBar .tab').forEach(t=>t.classList.toggle('active',t.dataset.view===id));document.querySelectorAll('.view').forEach(v=>v.classList.add('hidden'));const el=document.getElementById(id);if(el)el.classList.remove('hidden');const R={library:()=>renderLibrary((document.getElementById('libSearch')||{}).value||''),leader:()=>{populateLbSites();renderLeaderboard();},agentdb:renderAgents,batch:renderBatch,team:renderTeam,access:()=>{renderUsers();renderRoleMatrix();},audit:renderAudit,agentdash:renderAgentDash,evaldash:renderEval,frauddash:renderFraudDash,admindash:renderAdminDash,supervisordash:renderSupervisorDash,supqueue:renderSupQueue,trainerdash:renderTrainer,insights:renderInsights,home:buildHome,live:ftListMics,agentconvo:ftListMics};if(R[id])try{R[id]();}catch(e){console.warn('view',id,e);}}
function buildHome(){const r=ROLES[currentUser.role];document.getElementById('homeWelcome').textContent='Welcome, '+currentUser.name+'!';document.getElementById('homeRoleDesc').innerHTML='<span class="acc-role '+currentUser.role+'">'+r.em+' '+r.label+'</span> — '+r.desc;const ia=loadInteractions();const sc=ia.filter(x=>x.gapPct!=null);const avg=sc.length?Math.round(sc.reduce((a,x)=>a+x.gapPct,0)/sc.length):'—';document.getElementById('homeStats').innerHTML=[['Interactions',ia.length],['Avg Quality',avg+(avg==='—'?'':'%')],['Agents',loadAgents().length],['Users',loadUsers().length]].map(s=>'<div class="stat"><div class="n">'+s[1]+'</div><div class="l">'+s[0]+'</div></div>').join('');const acts=[];const q=[['live','🎙️ Start a call'],['agentconvo','🎬 Live agent convo'],['evaldash','✅ Review queue'],['insights','📈 Insights'],['supqueue','📥 Eval inbox'],['trainerdash','🧑‍🏫 Enrollments'],['batch','📤 Batch upload'],['access','🔐 Manage access'],['audit','🧾 Audit log'],['settings','⚙️ Configure AI']];q.forEach(([v,l])=>{if(can(v))acts.push('<button class="btn ghost" onclick="showView(\''+v+'\')">'+l+'</button>');});document.getElementById('homeActions').innerHTML=acts.join('');}
function saveUser(){const u=document.getElementById('uUser').value.trim().toLowerCase();const name=document.getElementById('uName').value.trim();const pass=document.getElementById('uPass').value;const role=document.getElementById('uRole').value;const emp=document.getElementById('uEmp').value.trim();const status=document.getElementById('uStatus').value;const msg=document.getElementById('uMsg');if(!u||!name||!pass){msg.style.color='var(--red)';msg.textContent='⚠️ Username, name & password required.';return;}const arr=loadUsers();const i=arr.findIndex(x=>x.user===u);const rec={user:u,name,pass,role,emp,status};if(i>=0)arr[i]=rec;else arr.push(rec);saveUsers(arr);clearUserForm();msg.style.color='var(--green)';msg.textContent='✅ Saved '+name+'.';renderUsers();fillSwitchUser();logAudit('User saved',u+' as '+role,'user');setTimeout(()=>msg.textContent='',3000);}
function clearUserForm(){['uUser','uName','uPass','uEmp'].forEach(id=>document.getElementById(id).value='');}
function renderUsers(){const f=(document.getElementById('uSearch').value||'').toLowerCase();const arr=loadUsers();const tbl=document.getElementById('uTable');while(tbl.rows.length>1)tbl.deleteRow(1);document.getElementById('uCount').textContent=arr.length;arr.filter(u=>(u.user+u.name+u.role+u.emp).toLowerCase().includes(f)).forEach(u=>{const r=tbl.insertRow(-1);r.innerHTML='<td>'+u.user+'</td><td>'+u.name+'</td><td><span class="acc-role '+u.role+'">'+ROLES[u.role].em+' '+ROLES[u.role].label+'</span></td><td>'+(u.emp||'—')+'</td><td>'+(u.status==='active'?'🟢 Active':'⛔ Disabled')+'</td><td><button style="font-size:11px;color:var(--teal);background:none;border:none;cursor:pointer" onclick="dmOpen(\''+u.user+'\')">💬</button> <button style="font-size:11px;color:var(--blue);background:none;border:none;cursor:pointer" onclick="editUser(\''+u.user+'\')">✏️</button> <button style="font-size:11px;color:var(--red);background:none;border:none;cursor:pointer" onclick="delUser(\''+u.user+'\')">🗑</button></td>';});}
function editUser(user){const u=loadUsers().find(x=>x.user===user);if(!u)return;document.getElementById('uUser').value=u.user;document.getElementById('uName').value=u.name;document.getElementById('uPass').value=u.pass;document.getElementById('uRole').value=u.role;document.getElementById('uEmp').value=u.emp||'';document.getElementById('uStatus').value=u.status;}
function delUser(user){if(user===currentUser.user){alert("Can't delete your own account.");return;}if(!confirm('Delete '+user+'?'))return;saveUsers(loadUsers().filter(x=>x.user!==user));renderUsers();fillSwitchUser();logAudit('User deleted',user,'user');}
function exportUsers(){let out="Username,Name,Role,Employee #,Status\n";loadUsers().forEach(u=>out+=[u.user,u.name,u.role,u.emp,u.status].map(csvEsc).join(',')+'\n');dl(out,"FANTASTIC_users.csv","text/csv");logAudit('Exported users','','export');}
function importUsers(ev){const f=ev.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const rows=parseCSV(r.result);if(rows.length<2)return;const arr=loadUsers();let n=0;for(let i=1;i<rows.length;i++){const [user,name,role,emp,status]=rows[i];if(!user)continue;const rec={user:user.toLowerCase(),name:name||user,pass:'changeme',role:(ROLES[role]?role:'agent'),emp:emp||'',status:status||'active'};const j=arr.findIndex(x=>x.user===rec.user);if(j>=0){rec.pass=arr[j].pass;arr[j]=rec;}else arr.push(rec);n++;}saveUsers(arr);renderUsers();fillSwitchUser();logAudit('Imported users',n+' rows','user');alert('✅ Imported '+n+' users.');};r.readAsText(f);ev.target.value='';}
function renderRoleMatrix(){document.getElementById('roleMatrix').innerHTML=Object.entries(ROLES).map(([k,r])=>'<div class="rolecard"><h4><span class="acc-role '+k+'">'+r.em+' '+r.label+'</span></h4><div class="note" style="margin:4px 0">'+r.desc+'</div><div class="perm-grid">'+r.perms.map(p=>'<span class="perm-chip">'+(PERM_LABELS[p]||p)+'</span>').join('')+'</div></div>').join('');}
function loadAudit(){return read('ft_audit',[]);}
function saveAudit(a){store('ft_audit',a.slice(0,2000));}
function logAudit(action,detail,cat){const arr=loadAudit();arr.unshift({ts:new Date().toISOString(),user:currentUser?currentUser.user:'system',role:currentUser?currentUser.role:'—',action:action||'',detail:detail||'',cat:cat||'general'});saveAudit(arr);const badge=document.getElementById('auditTabCount');if(badge){badge.textContent=arr.length;badge.classList.remove('hidden');}if(!document.getElementById('audit')?.classList.contains('hidden'))renderAudit();}
const AUDIT_CAT_LABEL={auth:'🔑 Auth',user:'👤 User',agent:'👥 Agent',config:'⚙️ Config',data:'🗂️ Data',export:'⬇️ Export',general:'•'};
function renderAudit(){const arr=loadAudit();const cat=(document.getElementById('auditCat')||{}).value||'all';const f=((document.getElementById('auditSearch')||{}).value||'').toLowerCase();const tbl=document.getElementById('auditTable');if(!tbl)return;while(tbl.rows.length>1)tbl.deleteRow(1);const shown=arr.filter(a=>(cat==='all'||a.cat===cat)&&(a.user+a.action+a.detail+a.role).toLowerCase().includes(f));document.getElementById('auditEmpty').style.display=arr.length?'none':'block';shown.slice(0,500).forEach(a=>{const r=tbl.insertRow(-1);r.innerHTML='<td>'+new Date(a.ts).toLocaleString()+'</td><td><b>'+a.user+'</b></td><td><span class="acc-role '+(a.role||'agent')+'">'+(a.role||'—')+'</span></td><td>'+(AUDIT_CAT_LABEL[a.cat]||a.cat)+'</td><td>'+a.action+'</td><td>'+(a.detail||'')+'</td>';});const k=document.getElementById('auditKpis');const today=new Date().toDateString();const byCat={};arr.forEach(a=>byCat[a.cat]=(byCat[a.cat]||0)+1);const topCat=Object.entries(byCat).sort((a,b)=>b[1]-a[1])[0];k.innerHTML='<div class="stat"><div class="n">'+arr.length+'</div><div class="l">Total Events</div></div><div class="stat"><div class="n">'+arr.filter(a=>new Date(a.ts).toDateString()===today).length+'</div><div class="l">Today</div></div><div class="stat"><div class="n">'+new Set(arr.map(a=>a.user)).size+'</div><div class="l">Distinct Users</div></div><div class="stat"><div class="n" style="font-size:18px">'+(topCat?(AUDIT_CAT_LABEL[topCat[0]]||topCat[0]):'—')+'</div><div class="l">Top Category</div></div>';}
function exportAudit(){const arr=loadAudit();let out="Timestamp,User,Role,Category,Action,Detail\n";arr.forEach(a=>out+=[a.ts,a.user,a.role,a.cat,a.action,a.detail].map(csvEsc).join(',')+'\n');dl(out,"FANTASTIC_audit_log.csv","text/csv");logAudit('Exported audit log',arr.length+' rows','export');}
function clearAudit(){if(!confirm('Clear the ENTIRE audit log?'))return;localStorage.removeItem('ft_audit');renderAudit();}
function loadNotif(){return read('ft_notif',[]);}
function saveNotif(a){store('ft_notif',a);}
function notify(toRole,toUser,msg,cat){const n=loadNotif();n.unshift({id:'N'+Date.now()+Math.floor(Math.random()*999),toRole,toUser:toUser||'',msg,cat:cat||'info',ts:new Date().toISOString(),read:false});saveNotif(n);refreshBell();}
function myNotifs(){const r=currentUser?currentUser.role:'';const u=currentUser?currentUser.user:'';return loadNotif().filter(n=>n.toRole===r||(n.toUser&&n.toUser===u));}
function refreshBell(){const c=document.getElementById('ftBellCount');if(!c)return;const un=myNotifs().filter(n=>!n.read).length;c.textContent=un;c.classList.toggle('hidden',un===0);const ic=document.getElementById('supInboxCount');if(ic){const pend=loadEvals().filter(e=>e.status==='sent').length;ic.textContent=pend;ic.classList.toggle('hidden',pend===0);}}
function toggleNotif(){const p=document.getElementById('ftNotifPanel');if(!p)return;p.classList.toggle('hidden');document.getElementById('ftDMPanel').classList.add('hidden');if(!p.classList.contains('hidden'))renderNotif();}
window.toggleNotif=toggleNotif;
function renderNotif(){const p=document.getElementById('ftNotifPanel');const ns=myNotifs();p.innerHTML='<div class="ph"><b>🔔 Notifications</b><button class="btn ghost" style="padding:4px 10px;font-size:11px" onclick="markAllRead()">Mark all read</button></div><div class="pb">'+(ns.length?ns.slice(0,40).map(n=>'<div class="lib-card" style="margin-bottom:8px;'+(n.read?'opacity:.6':'')+'"><div style="font-size:12.5px">'+esc(n.msg)+'</div><div class="note" style="margin-top:4px">'+new Date(n.ts).toLocaleString()+'</div></div>').join(''):'<div class="note">No notifications.</div>')+'</div>';}
function markAllRead(){const all=loadNotif();const r=currentUser.role,u=currentUser.user;all.forEach(n=>{if(n.toRole===r||n.toUser===u)n.read=true;});saveNotif(all);renderNotif();refreshBell();}
window.markAllRead=markAllRead;
function loadDM(){return read('ft_dm',[]);}
function saveDM(a){store('ft_dm',a);}
function tkey(a,b){return [a,b].sort().join('::');}
function dmUnread(){const me=currentUser?currentUser.user:'';return loadDM().filter(m=>m.to===me&&!m.read).length;}
function refreshDMBadge(){const c=document.getElementById('ftDMCount');if(!c)return;const u=dmUnread();c.textContent=u;c.classList.toggle('hidden',u===0);}
let _dmOpen=null;
function toggleDM(){const p=document.getElementById('ftDMPanel');if(!p)return;p.classList.toggle('hidden');document.getElementById('ftNotifPanel').classList.add('hidden');if(!p.classList.contains('hidden'))dmList();}
window.toggleDM=toggleDM;
function dmList(){const p=document.getElementById('ftDMPanel');_dmOpen=null;const me=currentUser.user;const msgs=loadDM().filter(m=>m.from===me||m.to===me);const map={};msgs.forEach(m=>{const o=m.from===me?m.to:m.from;(map[o]=map[o]||[]).push(m);});const users=loadUsers().filter(u=>u.user!==me&&u.status==='active');const rows=Object.keys(map).map(o=>{const arr=map[o].sort((a,b)=>new Date(a.ts)-new Date(b.ts));const last=arr[arr.length-1];const u=loadUsers().find(x=>x.user===o)||{name:o,role:'agent'};return {o,name:u.name,role:u.role,last,un:arr.filter(m=>m.to===me&&!m.read).length};}).sort((a,b)=>new Date(b.last.ts)-new Date(a.last.ts));p.innerHTML='<div class="ph"><b>💬 Messages</b><select class="sel" id="ftDMNew" style="max-width:160px;font-size:12px"><option value="">✍️ New…</option>'+users.map(u=>'<option value="'+u.user+'">'+ROLES[u.role].em+' '+esc(u.name)+'</option>').join('')+'</select></div><div class="pb" id="ftDMThreads">'+(rows.length?rows.map(r=>'<div class="lib-card" style="margin-bottom:8px;cursor:pointer" onclick="dmOpen(\''+r.o+'\')"><div class="lib-head"><div><b>'+ROLES[r.role].em+' '+esc(r.name)+'</b>'+(r.un?' <span class="pill-count">'+r.un+'</span>':'')+'<div class="note" style="margin-top:2px">'+esc((r.last.body||'').slice(0,54))+'</div></div><div class="note">'+new Date(r.last.ts).toLocaleTimeString()+'</div></div></div>').join(''):'<div class="note">No conversations yet.</div>')+'</div>';const nw=document.getElementById('ftDMNew');if(nw)nw.onchange=function(){if(this.value)dmOpen(this.value);};refreshDMBadge();}
function dmOpen(other){const p=document.getElementById('ftDMPanel');p.classList.remove('hidden');document.getElementById('ftNotifPanel').classList.add('hidden');_dmOpen=other;const me=currentUser.user;const all=loadDM();let ch=false;all.forEach(m=>{if(m.from===other&&m.to===me&&!m.read){m.read=true;ch=true;}});if(ch)saveDM(all);const u=loadUsers().find(x=>x.user===other)||{name:other,role:'agent'};const conv=all.filter(m=>tkey(m.from,m.to)===tkey(me,other)).sort((a,b)=>new Date(a.ts)-new Date(b.ts));p.innerHTML='<div class="ph"><b>'+ROLES[u.role].em+' '+esc(u.name)+'</b><button class="btn ghost" style="padding:4px 10px;font-size:11px" onclick="dmList()">← Back</button></div><div class="dmwrap"><div class="dmbody" id="ftDMBody">'+(conv.length?conv.map(m=>'<div class="msg '+(m.from===me?'ai':'cust')+'" style="max-width:88%"><div class="who">'+(m.from===me?'You':esc(u.name))+'</div><span class="txt">'+esc(m.body)+'</span><div class="note" style="margin-top:3px;opacity:.7">'+new Date(m.ts).toLocaleString()+'</div></div>').join(''):'<div class="note" style="text-align:center;margin-top:20px">Say hello 👋</div>')+'</div><div class="dminput"><input class="inp" id="ftDMInput" placeholder="Type a message…" style="flex:1" onkeydown="if(event.key===\'Enter\'){event.preventDefault();dmSend();}"><button class="btn" onclick="dmSend()">Send</button></div></div>';const b=document.getElementById('ftDMBody');if(b)b.scrollTop=b.scrollHeight;const inp=document.getElementById('ftDMInput');if(inp)inp.focus();refreshDMBadge();}
window.dmOpen=dmOpen;window.dmList=dmList;
function dmSend(){const other=_dmOpen;if(!other)return;const inp=document.getElementById('ftDMInput');const txt=(inp.value||'').trim();if(!txt)return;const all=loadDM();all.push({id:'DM'+Date.now()+Math.floor(Math.random()*999),from:currentUser.user,fromName:currentUser.name,to:other,body:txt,ts:new Date().toISOString(),read:false});saveDM(all);inp.value='';const u=loadUsers().find(x=>x.user===other);notify(u?u.role:'agent',other,'💬 New message from '+currentUser.name+': '+txt.slice(0,50),'dm');logAudit('Direct message','→ '+other,'data');dmOpen(other);}
window.dmSend=dmSend;
