function detectLang(text){const mode=(document.getElementById('liveLangMode')||{}).value;if(mode&&mode!=='auto')return mode;const t=(text||'').toLowerCase();const w=t.split(/[^a-zñ'-]+/).filter(Boolean);if(!w.length)return 'en';let en=0,tl=0,ceb=0,hil=0,ilo=0,war=0;w.forEach(x=>{if(EN_W.includes(x))en++;if(TL_W.includes(x))tl++;if(CEB_W.includes(x))ceb++;if(HIL_W.includes(x))hil++;if(ILO_W.includes(x))ilo++;if(WAR_W.includes(x))war++;});const iloMk=(t.match(/\b(agyaman|apay|kasano|siak|daytoy|naimbag|adda|awan|apo)\b/g)||[]).length;const warMk=(t.match(/\b(maupay|karuyag|tagpira|waray|hain|bulig|kumusta)\b/g)||[]).length;const cebMk=(t.match(/\b(gyud|jud|kaayo|unsa|asa|palihug|dili|nimo|nako)\b/g)||[]).length;const hilMk=(t.match(/\b(gid|sang|indi|ngaa|diin|subong|bulig)\b/g)||[]).length;const fil=Math.max(tl,ceb,hil,ilo,war);const total=en+fil||1;const filR=fil/total;if(en>=1&&fil>=1&&filR>0.15&&filR<0.85)return 'taglish';if(filR<0.5)return 'en';const scores=[['ilo',ilo+iloMk*2],['war',war+warMk*2],['ceb',ceb+cebMk*2],['hil',hil+hilMk*2],['tl',tl]];scores.sort((a,b)=>b[1]-a[1]);return scores[0][1]>0?scores[0][0]:'tl';}
function langLabel(l){return {tl:'TAGALOG',ceb:'CEBUANO',hil:'HILIGAYNON',ilo:'ILOKANO',war:'WARAY',taglish:'TAGLISH',en:'ENGLISH'}[l]||'ENGLISH';}
const END_RE=/\b(bye|goodbye|hang up|end the call|that'?s all|nothing else|no more|i'?m done|im done|paalam|tapos na|wala na( po)?|tama na|okay na( po)?|ok na( po)?|human na|amo na|maupay nga adlaw,? paalam|agyaman.{0,6}paalam)\b/i;
function detectEndIntent(text){return END_RE.test((text||'').trim());}
