function localize(text,lang){if(lang==='en')return text;const lead={tl:'Sige po, ',ceb:'Sige, ',hil:'Sige, ',ilo:'Wen, ',war:'Sige, ',taglish:'Sure po, '}[lang]||'';const tail={tl:' Sana po nakatulong ito.',ceb:' Sana nakatabang ni.',hil:' Sana nakabulig ini.',ilo:' Sapay koma a nakatulong daytoy.',war:' Sana nakabulig ini.',taglish:' Hope this helps po.'}[lang]||'';return lead+text+tail;}
const POS=["thank","salamat","great","good","happy","perfect","nice","ok","okay","yes","sige","maganda","galing","ayos","maayo","huo","oo","agyaman","naimbag","maupay"];
const NEG=["angry","bad","terrible","worst","hate","slow","broken","problem","complaint","refund","cancel","galit","pangit","ayaw","reklamo","sobra","budlay","lisod","hinay","akig","masuko"];
function scoreSentiment(t){t=t.toLowerCase();let p=POS.reduce((a,w)=>a+(t.includes(w)?1:0),0),n=NEG.reduce((a,w)=>a+(t.includes(w)?1:0),0);if(n>p)return"neg";if(p>n)return"pos";return"neu";}
function updateSenti(){const tot=sPos+sNeu+sNeg||1,pp=Math.round(sPos/tot*100),nn=Math.round(sNeg/tot*100),up=100-pp-nn;const P=document.getElementById('sPos'),N=document.getElementById('sNeu'),G=document.getElementById('sNeg');if(!P)return;P.style.width=pp+'%';P.textContent=pp+'%';N.style.width=up+'%';N.textContent=up+'%';G.style.width=nn+'%';G.textContent=nn+'%';}
