async function ftListMics(){let devices=[];try{devices=await navigator.mediaDevices.enumerateDevices();}catch(e){}const mics=devices.filter(d=>d.kind==='audioinput');document.querySelectorAll('.ftMicSel').forEach(sel=>{const cur=window.ftMicId;sel.innerHTML='<option value="">🎤 System default mic</option>'+mics.map((m,i)=>{const virt=/virtual|vb-?audio|cable|voicemeeter|obs|blackhole|stereo mix/i.test(m.label||'')?' · virtual':'';return '<option value="'+m.deviceId+'">'+(m.label||('Microphone '+(i+1)))+virt+'</option>';}).join('');if(cur&&mics.some(m=>m.deviceId===cur))sel.value=cur;});return mics;}
async function ftGrantMic(){try{const s=await navigator.mediaDevices.getUserMedia(window.ftMicConstraint());s.getTracks().forEach(t=>t.stop());}catch(e){try{const s2=await navigator.mediaDevices.getUserMedia({audio:true});s2.getTracks().forEach(t=>t.stop());}catch(_){}}await ftListMics();ftStartMeter();}
window.ftListMics=ftListMics;window.ftGrantMic=ftGrantMic;
window.ftOnMicChange=function(v){window.ftMicId=v;document.querySelectorAll('.ftMicSel').forEach(s=>{if(s.value!==v)s.value=v;});const remember=(document.getElementById('ftMicDefault')&&document.getElementById('ftMicDefault').checked)||(document.getElementById('ftMicDefault2')&&document.getElementById('ftMicDefault2').checked);if(remember){try{localStorage.setItem('ft_micDefault',v||'');}catch(e){}}try{logAudit('Microphone changed',(v?'device':'system default')+(remember?' (default)':''),'config');}catch(e){}try{if(callActive&&sttMode==='azure'){stopAzureRec();setTimeout(()=>startRec(),300);}}catch(e){}try{setStatus('Mic set: '+(v?'selected device':'system default'),'');}catch(e){}ftStartMeter();};
let _mS=null,_mC=null,_mR=null;
async function ftStartMeter(){ftStopMeter();try{_mS=await navigator.mediaDevices.getUserMedia(window.ftMicConstraint());_mC=new (window.AudioContext||window.webkitAudioContext)();const src=_mC.createMediaStreamSource(_mS);const an=_mC.createAnalyser();an.fftSize=512;src.connect(an);const data=new Uint8Array(an.frequencyBinCount);const bars=['ftLvlBar','ftLvlBar2'].map(id=>document.getElementById(id));const loop=()=>{an.getByteTimeDomainData(data);let pk=0;for(let i=0;i<data.length;i++){const v=Math.abs(data[i]-128);if(v>pk)pk=v;}const pct=Math.min(100,Math.round(pk/128*180));bars.forEach(b=>{if(b)b.style.width=pct+'%';});_mR=requestAnimationFrame(loop);};loop();}catch(e){}}
function ftStopMeter(){try{if(_mR)cancelAnimationFrame(_mR);}catch(e){}try{_mS&&_mS.getTracks().forEach(t=>t.stop());}catch(e){}try{_mC&&_mC.close();}catch(e){}_mS=_mC=_mR=null;['ftLvlBar','ftLvlBar2'].forEach(id=>{const b=document.getElementById(id);if(b)b.style.width='0';});}
window.ftStartMeter=ftStartMeter;window.ftStopMeter=ftStopMeter;
try{navigator.mediaDevices.addEventListener('devicechange',ftListMics);}catch(e){}
let azureCfg={enabled:false,key:'',region:'southeastasia',voice:'fil-PH-BlessicaNeural',style:''};
const azureAudio=new Audio();let curLang='en';
function setLivePill(l){curLang=l;const p=document.getElementById('liveLangPill');if(p)p.textContent=langLabel(l);}
function voiceForLang(l){const rl=(document.getElementById('recLang')||{}).value||'en-US';if(rl==='ja-JP')return 'ja-JP-NanamiNeural';if(rl==='zh-HK')return 'zh-HK-HiuMaanNeural';if(['tl','ceb','hil','ilo','war','taglish'].includes(l))return 'fil-PH-BlessicaNeural';if(rl==='es-ES')return 'es-ES-ElviraNeural';return 'en-US-AvaMultilingualNeural';}
async function azureSynth(text,voiceOverride){const voice=voiceOverride||azureCfg.voice;const loc=voice.substring(0,5);const inner=azureCfg.style?'<mstts:express-as style="'+azureCfg.style+'">'+esc(text)+'</mstts:express-as>':esc(text);const ssml='<speak version="1.0" xmlns="http://www.w3.org/2001/10/synthesis" xmlns:mstts="https://www.w3.org/2001/mstts" xml:lang="'+loc+'"><voice name="'+voice+'">'+inner+'</voice></speak>';const res=await fetch('https://'+azureCfg.region+'.tts.speech.microsoft.com/cognitiveservices/v1',{method:'POST',headers:{'Ocp-Apim-Subscription-Key':azureCfg.key,'Content-Type':'application/ssml+xml','X-Microsoft-OutputFormat':'audio-24khz-96kbitrate-mono-mp3'},body:ssml});if(!res.ok)throw new Error('Azure TTS '+res.status);return URL.createObjectURL(new Blob([await res.arrayBuffer()],{type:'audio/mpeg'}));}
function pickBrowserVoice(l){const rl=(document.getElementById('recLang')||{}).value||'en-US';let want=['tl','ceb','hil','ilo','war','taglish'].includes(l)?'fil':(rl==='ja-JP'?'ja':rl==='zh-HK'?'zh':rl==='es-ES'?'es':'en');return voices.find(v=>v.lang&&v.lang.toLowerCase().startsWith(want))||null;}
function browserSpeak(text,l){if(!synth)return;synth.cancel();const u=new SpeechSynthesisUtterance(text);const pv=pickBrowserVoice(l);if(pv)u.voice=pv;else{const vi=document.getElementById('ttsVoice').value;if(voices[vi])u.voice=voices[vi];}u.rate=parseFloat(document.getElementById('rate').value);u.onstart=()=>{orb&&orb.classList.add('speaking');setStatus('Speaking…','live');};u.onend=()=>{orb&&orb.classList.remove('speaking');if(callActive){setStatus('Listening…','live');startRec();}};synth.speak(u);}
function speak(text,langHint){const l=langHint||curLang;if(azureCfg.enabled&&azureCfg.key){setStatus('Synthesizing…','live');azureSynth(text,voiceForLang(l)).then(url=>{azureAudio.src=url;azureAudio.onplay=()=>{orb&&orb.classList.add('speaking');setStatus('Speaking (Azure)…','live');};azureAudio.onended=()=>{orb&&orb.classList.remove('speaking');if(callActive){setStatus('Listening…','live');startRec();}};azureAudio.play();}).catch(e=>browserSpeak(text,l));}else browserSpeak(text,l);}
function stopSpeaking(){synth&&synth.cancel();try{azureAudio.pause();}catch(e){}}
const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
let rec=null,callActive=false,muted=false,interimEl=null,sttMode='browser',azRec=null,azRunning=false;
function recLangFor(){let v=(document.getElementById('recLang')||{}).value||'en-US';if(v.indexOf('fil-PH-')===0)v='fil-PH';return v;}
function startRec(){if(!callActive||muted)return;if(sttMode==='azure'&&azureCfg.key&&window.SpeechSDK)startAzureRec();else startBrowserRec();}
function stopRec(){try{rec&&rec.abort();}catch(e){}stopAzureRec();orb&&orb.classList.remove('listening');}
function startBrowserRec(){if(!SR){const t=document.getElementById('transcript');if(t)t.innerHTML='<div class="note" style="color:var(--red)">⚠️ No browser speech recognition. Use Chrome/Edge or enable Azure STT.</div>';return;}try{if(rec)rec.abort();}catch(e){}try{rec=new SR();rec.continuous=false;rec.interimResults=true;rec.lang=recLangFor();rec.onresult=e=>{let interim="",final="";for(let i=e.resultIndex;i<e.results.length;i++){const tr=e.results[i][0].transcript;if(e.results[i].isFinal)final+=tr;else interim+=tr;}if(interim){if(!interimEl)interimEl=addMsg("cust","",true);interimEl.querySelector('.txt').textContent=interim;}if(final){if(interimEl){interimEl.remove();interimEl=null;}handleCustomer(final.trim());}};rec.onend=()=>{orb&&orb.classList.remove('listening');if(sttMode==='browser'&&callActive&&!muted&&!(synth&&synth.speaking))setTimeout(startBrowserRec,300);};rec.onerror=ev=>{orb&&orb.classList.remove('listening');if(ev&&(ev.error==='not-allowed'||ev.error==='service-not-allowed')){const t=document.getElementById('transcript');if(t){const d=document.createElement('div');d.className='note';d.style.color='var(--red)';d.innerHTML='🎙️ Mic blocked. Allow it via the padlock, then press Start.';t.appendChild(d);}}};rec.start();orb&&orb.classList.add('listening');}catch(e){setTimeout(()=>{try{rec&&rec.start();}catch(_){}} ,400);}}
function azAudioCfg(){return window.ftMicId?SpeechSDK.AudioConfig.fromMicrophoneInput(window.ftMicId):SpeechSDK.AudioConfig.fromDefaultMicrophoneInput();}
function startAzureRec(){if(azRunning)return;try{const cfg=SpeechSDK.SpeechConfig.fromSubscription(azureCfg.key,azureCfg.region);cfg.speechRecognitionLanguage=recLangFor();azRec=new SpeechSDK.SpeechRecognizer(cfg,azAudioCfg());azRec.recognizing=(s,e)=>{const t=e.result.text;if(!t)return;if(!interimEl)interimEl=addMsg("cust","",true);interimEl.querySelector('.txt').textContent=t;};azRec.recognized=(s,e)=>{if(e.result.reason===SpeechSDK.ResultReason.RecognizedSpeech){if(interimEl){interimEl.remove();interimEl=null;}const t=e.result.text.trim();if(t)handleCustomer(t);}};azRec.canceled=()=>azFallback();azRec.startContinuousRecognitionAsync(()=>{azRunning=true;orb&&orb.classList.add('listening');setStatus('Listening (Azure · '+(window.ftMicId?'selected mic':'default')+')…','live');},()=>azFallback());}catch(e){azFallback();}}
function stopAzureRec(){if(azRec&&azRunning){try{azRec.stopContinuousRecognitionAsync(()=>{try{azRec.close();}catch(e){}azRec=null;azRunning=false;});}catch(e){azRunning=false;}}}
function azFallback(){azRunning=false;sttMode='browser';document.getElementById('sttAzure')?.classList.remove('on');document.getElementById('sttBrowser')?.classList.add('on');if(callActive&&!muted)setTimeout(startBrowserRec,300);}
const rlSel=document.getElementById('recLang');if(rlSel)rlSel.addEventListener('change',()=>{if(callActive&&sttMode==='browser'){try{rec&&rec.abort();}catch(e){}}});
const tEl=document.getElementById('transcript');
function addMsg(who,text,interim,labelOverride){document.getElementById('emptyT')?.remove();const m=document.createElement('div');m.className='msg '+who+(interim?' interim':'');const isCust=(roleMode==='agent'&&who==='cust')||(roleMode==='customer'&&who==='ai');const senti=isCust&&!interim?scoreSentiment(text):null;const face=senti==='pos'?'😊':senti==='neg'?'😠':senti==='neu'?'😐':'';let label=labelOverride;if(!label){if(who==='sup')label='Supervisor';else if(roleMode==='customer')label=who==='cust'?'Agent (You)':'Customer (AI)';else label=who==='cust'?'Customer':(document.getElementById('agInput').value||'FANTASTIC AI');}m.innerHTML='<div class="who">'+label+'</div><span class="txt">'+text+'</span>'+(face?'<span class="senti">'+face+'</span>':'');tEl.appendChild(m);tEl.scrollTop=tEl.scrollHeight;return m;}
let convo=[],custTurns=0,startTime=0,timerInt=null,roleMode='agent',callEnding=false;
function scoreCustomer(text){const s=scoreSentiment(text);if(s==='pos'){sPos++;negStreak=0;}else if(s==='neg'){sNeg++;negStreak++;}else{sNeu++;negStreak=0;}updateSenti();updateMood();return s;}
function aiReply(text){const t=text.toLowerCase();const {best,score}=kbMatch(text);let lang=detectLang(text);setLivePill(lang);if(detectEndIntent(text))return {a:LINES.endack[lang]||LINES.endack.en,intent:'Closing',kb:false,end:true,lang};const neg=scoreSentiment(text)==='neg'||/(angry|galit|akig|masuko|reklamo|complaint|budlay|lisod)/i.test(t);let pre=neg?((LINES.apology[lang]||LINES.apology.en)+' '+(LINES.empathy[lang]||LINES.empathy.en)+' '):'';if(/(thank|salamat|maayo|agyaman)/.test(t)&&t.length<40)return {a:LINES.closing[lang]||LINES.closing.en,intent:'Closing',kb:false,lang};if(/(hi|hello|good morning|kumusta|kamusta|magandang|maayong|naimbag)/.test(t)&&t.length<50)return {a:(LINES.greeting[lang]||LINES.greeting.en)(document.getElementById('brandInput').value),intent:'Greeting',kb:false,lang};if(best&&score>0)return {a:pre+localize(best.a,lang),intent:best.q,kb:true,lang,empathized:!!pre};return {a:pre+(LINES.clarify[lang]||LINES.clarify.en),intent:'Clarification',kb:false,lang,empathized:!!pre};}
function handleCustomer(text){if(!text)return;if(roleMode==='agent')handleTurnAgentMode(text);else handleTurnCustomerMode(text);}
function handleTurnAgentMode(text){const flags=fraudScan(text);const shown=maskSensitive(text);addMsg('cust',shown);const s=scoreCustomer(text);custTurns++;const custEnd=detectEndIntent(text);convo.push({who:'cust',role:'customer',text:shown,raw:text,s,flags:flags.map(f=>f.id),end:custEnd});if(custEnd)showEndFlag('🧑 Customer signaled end of call — wrapping up & closing.');const r=aiReply(text);if(flags.length)applyFraudAssist(flags);checkSupervisorTriggers(text,s,flags);liveAiGuide();setTimeout(()=>{addMsg('ai',r.a);convo.push({who:'ai',role:'agent',text:r.a,intent:r.intent,kb:r.kb,end:r.end,empathized:r.empathized});speak(r.a,r.lang);if(custEnd||r.end){callEnding=true;setTimeout(()=>{if(callActive)endCall();},1900);}},450);}
function handleTurnCustomerMode(agentText){addMsg('cust',agentText,false,'Agent (You)');custTurns++;convo.push({who:'cust',role:'agent',text:agentText,raw:agentText});const agentEnd=detectEndIntent(agentText);if(agentEnd)showEndFlag('🎧 Agent signaled end of call.');const r=customerReply(agentText);const s=scoreCustomer(r.a);convo.push({who:'ai',role:'customer',text:r.a,raw:r.a,s,intent:r.intent,kb:false});checkSupervisorTriggers(r.a,s,[]);liveAiGuide();setTimeout(()=>{addMsg('ai',r.a,false,'Customer (AI)');speak(r.a,curLang);if(r.resolved)setStatus('Scenario resolved ✔','live');if(agentEnd){callEnding=true;setTimeout(()=>{if(callActive)endCall();},1500);}},450);}
function showEndFlag(msg){const f=document.getElementById('endFlag');if(f){f.textContent='📞 '+msg;f.classList.add('show');}}
const SCENARIOS={billing:{label:"Billing dispute",open:"Hi, my bill this month is way higher than usual and I don't understand why.",need:["itemize","explain","check","dispute","credit","refund"],mood:"neg"},outage:{label:"Service outage",open:"My internet has been down since morning. Fix this now.",need:["outage","maintenance","restore","technician","ticket","update"],mood:"neg"},cancel:{label:"Angry cancellation",open:"I've had enough. I want to cancel my account today. This is the worst.",need:["sorry","understand","retain","offer","fix","resolve","apolog"],mood:"neg"},upgrade:{label:"Plan upgrade",open:"Hi! I keep running out of data. What are my upgrade options?",need:["compare","recommend","bundle","upgrade","data","process"],mood:"neu"},refund:{label:"Refund request",open:"I was charged twice and I'd like a refund.",need:["refund","verify","file","reference","process","credit"],mood:"neu"}};
let scen=null,scenStep=0,scenSat=50,scenResolved=false;
function pickScenario(){let key=document.getElementById('scenarioPick').value;if(key==='random'){const ks=Object.keys(SCENARIOS);key=ks[Math.floor(Math.random()*ks.length)];}scen=SCENARIOS[key];scenStep=0;scenSat=scen.mood==='neg'?30:55;scenResolved=false;return scen;}
function customerReply(a){const t=a.toLowerCase();const emp=/(sorry|apolog|understand|pasensya|pasaylo|salamat)/i.test(t);const addr=scen.need.some(w=>t.includes(w));const close=/(anything else|glad to help|thank you for calling)/i.test(t);if(emp)scenSat+=15;if(addr)scenSat+=20;scenSat=Math.max(0,Math.min(100,scenSat));scenStep++;if((addr&&scenSat>=70)||close&&scenSat>=60){scenResolved=true;return {a:pick(["Oh, that helps a lot. Thank you, that's all — goodbye!","Okay, salamat! Wala na po, paalam.","Great, that resolves it. Bye!"]),intent:"Resolved",resolved:true};}if(scenStep>=5&&scenSat<50)return {a:pick(["I'm not satisfied. Can I speak to your supervisor?","Escalate me to a manager please."]),intent:"Escalation",resolved:false};if(emp&&!addr)return {a:pick(["I appreciate that, but what can you do?","So what are the next steps?"]),intent:"Probing",resolved:false};if(scenSat<40)return {a:pick(["Are you even listening? Please fix this.","You're not helping."]),intent:"Frustrated",resolved:false};return {a:pick(["Okay, so what do you suggest?","Can you explain more?","And what happens next?"]),intent:"Continuing",resolved:false};}
function pick(a){return a[Math.floor(Math.random()*a.length)];}
function setRole(mode){roleMode=mode;document.getElementById('roleAgent').classList.toggle('on',mode==='agent');document.getElementById('roleCustomer').classList.toggle('on',mode==='customer');document.getElementById('scenarioPick').style.display=mode==='customer'?'':'none';document.getElementById('agName').textContent=mode==='customer'?'Customer (AI)':document.getElementById('agInput').value;}
function setStatus(txt,cls){const h=document.getElementById('hdrStatus');if(h){h.textContent=txt;document.getElementById('hdrDot').className='dot'+(cls==='live'?' live':'');}}
function fmt(s){const m=Math.floor(s/60),ss=s%60;return String(m).padStart(2,'0')+':'+String(ss).padStart(2,'0');}
function tick(){const el=Math.floor((Date.now()-startTime)/1000);document.getElementById('timer').textContent=fmt(el);checkDurationTrigger(el);}
let camStream=null,camOn=false,camRAF=null,moodVal=50,_faceReady=false;
async function loadFaceModels(){if(_faceReady||!window.faceapi)return;try{const M='https://cdn.jsdelivr.net/npm/@vladmandic/face-api@latest/model/';await faceapi.nets.tinyFaceDetector.loadFromUri(M);await faceapi.nets.faceExpressionNet.loadFromUri(M);_faceReady=true;}catch(e){console.warn('face models',e);}}
async function toggleCamera(){if(camOn){stopCamera();return;}try{camStream=await navigator.mediaDevices.getUserMedia({video:{width:320,height:240,facingMode:'user'}});const v=document.getElementById('camVideo');v.srcObject=camStream;v.classList.remove('hidden');document.getElementById('camOff').classList.add('hidden');document.getElementById('camBadge').classList.remove('hidden');document.getElementById('btnCam').classList.add('on');camOn=true;loadFaceModels().then(()=>setTimeout(faceLoop,500));logAudit('Camera enabled','face-api mood tracking','config');}catch(e){document.getElementById('camOff').textContent='📷 Camera blocked. Allow access and retry.';}}
function stopCamera(){camOn=false;if(camRAF)cancelAnimationFrame(camRAF);try{camStream&&camStream.getTracks().forEach(t=>t.stop());}catch(e){}camStream=null;const v=document.getElementById('camVideo');if(v){v.classList.add('hidden');v.srcObject=null;}document.getElementById('camOff')?.classList.remove('hidden');document.getElementById('camBadge')?.classList.add('hidden');document.getElementById('btnCam')?.classList.remove('on');}
function faceLoop(){if(!camOn)return;const v=document.getElementById('camVideo');if(_faceReady&&v&&v.videoWidth){faceapi.detectSingleFace(v,new faceapi.TinyFaceDetectorOptions({inputSize:160,scoreThreshold:0.4})).withFaceExpressions().then(det=>{if(det&&det.expressions){const e=det.expressions;const pos=(e.happy||0)+0.4*(e.surprised||0);const neg=(e.angry||0)+(e.sad||0)+(e.fearful||0)+0.5*(e.disgusted||0);let v2=Math.max(3,Math.min(98,50+pos*55-neg*60));moodVal=moodVal*0.7+v2*0.3;const top=Object.entries(e).sort((a,b)=>b[1]-a[1])[0];renderMood(moodVal,'face-api: '+top[0]+' '+Math.round(top[1]*100)+'%',true);}}).catch(()=>{});}camRAF=requestAnimationFrame(()=>setTimeout(faceLoop,220));}
function moodFaceFor(v){return v>=75?'😀':v>=60?'🙂':v>=45?'😐':v>=30?'😕':'😣';}
function moodLabelFor(v){return v>=75?'Positive':v>=60?'Upbeat':v>=45?'Neutral':v>=30?'Strained':'Stressed';}
function renderMood(v,exp,faceOK){const f=document.getElementById('moodFace'),lb=document.getElementById('moodLabel'),bar=document.getElementById('moodBar'),det=document.getElementById('moodDetail'),conf=document.getElementById('moodConf');if(!f)return;f.textContent=moodFaceFor(v);lb.textContent=moodLabelFor(v);bar.style.width=Math.round(v)+'%';det.textContent='Expression: '+(exp||'—');conf.textContent=(faceOK?'👤 face ✓':'')+' mood '+Math.round(v)+'/100';}
function updateMood(){if(!camOn){const v=Math.max(5,Math.min(95,55+(sPos-sNeg)*8));moodVal=v;renderMood(v,'(camera off — voice sentiment)',false);}}
const btnStart=document.getElementById('btnStart'),btnEnd=document.getElementById('btnEnd'),btnMute=document.getElementById('btnMute'),btnCam=document.getElementById('btnCam');
