async function ensureMic(){try{const s=await navigator.mediaDevices.getUserMedia(window.ftMicConstraint());s.getTracks().forEach(t=>t.stop());await ftListMics();return true;}catch(e){try{const s2=await navigator.mediaDevices.getUserMedia({audio:true});s2.getTracks().forEach(t=>t.stop());}catch(_){}return false;}}
btnStart.onclick=async()=>{if(!SR&&sttMode==='browser'){alert("Speech recognition needs Chrome/Edge, or enable Azure STT.");return;}await ensureMic();callActive=true;callEnding=false;convo=[];custTurns=0;sPos=0;sNeu=0;sNeg=0;negStreak=0;updateSenti();resetFraud();resetSupervisor();document.getElementById('fraudAlert').classList.remove('show');document.getElementById('endFlag').classList.remove('show');document.getElementById('liveQAbody').classList.add('hidden');document.getElementById('liveQAempty').classList.remove('hidden');document.getElementById('liveQAScore').textContent='';document.getElementById('micInd').classList.remove('hidden');tEl.innerHTML="";startTime=Date.now();timerInt=setInterval(tick,1000);btnStart.disabled=true;btnEnd.disabled=false;btnMute.disabled=false;updateMood();if(roleMode==='customer'){const sc=pickScenario();document.getElementById('agName').textContent='Customer (AI)';scoreCustomer(sc.open);convo.push({who:'ai',role:'customer',text:sc.open,raw:sc.open,intent:'Opening'});addMsg('ai',sc.open,false,'Customer (AI)');speak(sc.open,'en');setStatus('Training — you are the agent','live');}else{document.getElementById('agName').textContent=document.getElementById('agInput').value;setLivePill('en');const greet=(LINES.greeting.en)(document.getElementById('brandInput').value);convo.push({who:'ai',role:'agent',text:greet,intent:'Greeting'});addMsg('ai',greet);speak(greet,'en');}setTimeout(startRec,200);};
