const THEMES=[{p:'#0e7c7b',a:'#f4c542'},{p:'#a4248f',a:'#f4c542'},{p:'#7c1f2e',a:'#e2c044'},{p:'#4c1d95',a:'#f43f5e'},{p:'#0f172a',a:'#38bdf8'},{p:'#065f46',a:'#a3e635'}];
