THEMES.forEach(t=>{const d=document.createElement('div');d.className='sw';d.style.background='linear-gradient(135deg,'+t.p+' 50%,'+t.a+' 50%)';d.onclick=()=>{document.getElementById('colPrimary').value=t.p;document.getElementById('colAccent').value=t.a;applyBranding();};swEl.appendChild(d);});
function shade(h,p){const n=parseInt(h.slice(1),16);let r=(n>>16)&255,g=(n>>8)&255,b=n&255;r=Math.round(r*(1-p));g=Math.round(g*(1-p));b=Math.round(b*(1-p));return'#'+(r<<16|g<<8|b).toString(16).padStart(6,'0');}
function tint(h,p){const n=parseInt(h.slice(1),16);let r=(n>>16)&255,g=(n>>8)&255,b=n&255;r=Math.round(r+(255-r)*p);g=Math.round(g+(255-g)*p);b=Math.round(b+(255-b)*p);return'#'+(r<<16|g<<8|b).toString(16).padStart(6,'0');}
function applyBranding(){const p=document.getElementById('colPrimary').value,a=document.getElementById('colAccent').value,rs=document.documentElement.style;rs.setProperty('--teal',p);rs.setProperty('--teal-dark',shade(p,.28));rs.setProperty('--teal-light',tint(p,.25));rs.setProperty('--yellow',a);rs.setProperty('--yellow-dark',shade(a,.22));document.getElementById('brandLogo').textContent=document.getElementById('brandInit').value||'FT';const nm=document.getElementById('brandName').value||'FANTASTIC TOOL';document.getElementById('brandTitle').innerHTML=nm+' <span class="badge">v3.2</span>';document.getElementById('brandTag').textContent=document.getElementById('brandTagIn').value;}
['colPrimary','colAccent','brandName','brandInit','brandTagIn'].forEach(id=>{const el=document.getElementById(id);if(el)el.oninput=applyBranding;});
document.getElementById('agInput').oninput=e=>document.getElementById('agName').textContent=e.target.value;
function hbars(id,rows){const el=document.getElementById(id);if(!el)return;el.innerHTML="";if(!rows.length){el.innerHTML='<div class="note">No data yet.</div>';return;}const max=Math.max(...rows.map(r=>r.v));rows.forEach(r=>{const d=document.createElement('div');d.className='hbar-row';d.innerHTML='<span class="name">'+r.n+'</span><div class="track"><span style="width:'+Math.max(12,r.v/max*100)+'%">'+r.v+'</span></div>';el.appendChild(d);});}
function sparkline(id,vals,max){const el=document.getElementById(id);if(!el)return;el.innerHTML="";vals.forEach(v=>{const c=document.createElement('div');c.className='col';c.style.height=Math.max(4,(v/max)*100)+'%';el.appendChild(c);});}
const FRAUD_RULES=[{id:'card',name:'Card Number',sev:'critical',score:35,desc:'Full PAN (PCI-DSS)',on:true,test:t=>{const m=t.replace(/[ -]/g,'').match(/\d{13,16}/g);if(!m)return null;return m.find(luhn)?['Card number']:null;}},{id:'cvv',name:'CVV / Security Code',sev:'critical',score:30,desc:'Card security code',on:true,test:t=>/(cvv|cvc|security code).{0,20}\d{3,4}/i.test(t)?['CVV shared']:null},{id:'otp',name:'OTP / PIN / Password',sev:'critical',score:32,desc:'OTP/PIN disclosed',on:true,test:t=>/(otp|one[ -]?time|pin|password).{0,25}\d{3,8}|(my (pin|password|otp) is)/i.test(t)?['OTP/PIN disclosed']:null},{id:'giftcard',name:'Gift Card / Crypto',sev:'high',score:25,desc:'Scam payment',on:true,test:t=>/(gift ?card|bitcoin|crypto|usdt|steam card|itunes)/i.test(t)?['Unusual payment']:null},{id:'remote',name:'Remote Access',sev:'high',score:24,desc:'AnyDesk/TeamViewer',on:true,test:t=>/(anydesk|teamviewer|remote (access|desktop))/i.test(t)?['Remote access']:null},{id:'pressure',name:'Pressure / Urgency',sev:'med',score:15,desc:'Threats/urgency',on:true,test:t=>/(right now|immediately|suspend|arrest|urgent|last warning|or else)/i.test(t)?['Pressure']:null},{id:'bait',name:'Prize / Lottery Bait',sev:'med',score:14,desc:'Winnings lure',on:true,test:t=>/(you won|congratulations.{0,20}prize|claim your (prize|reward)|lottery)/i.test(t)?['Prize bait']:null}];
function luhn(n){let s=0,a=false;for(let i=n.length-1;i>=0;i--){let d=+n[i];if(a){d*=2;if(d>9)d-=9;}s+=d;a=!a;}return s%10===0;}
let fraudFlags=[],fraudScore=0,maskCount=0;
function fraudScan(text){const found=[];FRAUD_RULES.forEach(r=>{if(!r.on)return;const res=r.test(text);if(res)found.push({id:r.id,name:r.name,sev:r.sev,score:r.score,evidence:res[0]});});if(found.length){found.forEach(f=>{fraudScore=Math.min(100,fraudScore+f.score);fraudFlags.push(f);logFraud(f);});updateFraudUI();}return found;}
function maskSensitive(text){if(!document.getElementById('maskToggle')?.checked)return text;let out=text,m=false;out=out.replace(/\b(\d[ -]?){13,16}\b/g,x=>{const d=x.replace(/[ -]/g,'');if(d.length>=13&&d.length<=16&&luhn(d)){m=true;return '•••• •••• •••• '+d.slice(-4);}return x;});out=out.replace(/((?:cvv|cvc|pin|otp|password|code)\D{0,15})(\d{3,8})/gi,(x,p1)=>{m=true;return p1+'••••';});if(m)maskCount++;return out;}
function sevRank(s){return s==='critical'?3:s==='high'?2:1;}
function logFraud(f){const tbl=document.getElementById('fraudLog');if(!tbl)return;document.getElementById('fraudEmpty')?.classList.add('hidden');const r=tbl.insertRow(1);r.innerHTML='<td>'+new Date().toLocaleTimeString()+'</td><td>'+f.name+'</td><td><span class="sev '+f.sev+'">'+f.sev+'</span></td><td>'+f.evidence+'</td>';}
function updateFraudUI(){const arc=document.getElementById('gaugeArc');if(!arc)return;arc.style.strokeDashoffset=126-(fraudScore/100*126);const col=fraudScore>=60?'#dc2626':fraudScore>=30?'#f59e0b':'#16a34a';arc.style.stroke=col;const rn=document.getElementById('riskNum');rn.textContent=fraudScore;rn.style.color=col;document.getElementById('riskLab').textContent=fraudScore>=60?'HIGH RISK':fraudScore>=30?'Elevated':'Low risk';document.getElementById('fTotal').textContent=fraudFlags.length;document.getElementById('fCrit').textContent=fraudFlags.filter(f=>f.sev==='critical').length;document.getElementById('fMask').textContent=maskCount;const mx=fraudFlags.reduce((a,f)=>Math.max(a,sevRank(f.sev)),0);document.getElementById('fMax').textContent=mx===3?'🔴 Critical':mx===2?'🟠 High':mx===1?'🟡 Medium':'—';}
function applyFraudAssist(flags){const top=flags.sort((a,b)=>sevRank(b.sev)-sevRank(a.sev))[0];const al=document.getElementById('fraudAlert');document.getElementById('fraudAlertMsg').textContent=' '+top.name+' — risk '+fraudScore+'/100.';al.classList.add('show');setTimeout(()=>al.classList.remove('show'),8000);}
function renderRules(){const el=document.getElementById('ruleList');if(!el)return;el.innerHTML=FRAUD_RULES.map(r=>'<div class="rule"><div class="info"><b>'+r.name+'</b> <span class="sev '+r.sev+'">'+r.sev+'</span><p>'+r.desc+'</p></div><label class="switch"><input type="checkbox" '+(r.on?'checked':'')+' onchange="toggleRule(\''+r.id+'\',this.checked)"><span class="slider"></span></label></div>').join('');}
function toggleRule(id,on){const r=FRAUD_RULES.find(x=>x.id===id);if(r)r.on=on;}
function resetFraud(){fraudFlags=[];fraudScore=0;maskCount=0;const tbl=document.getElementById('fraudLog');if(tbl)while(tbl.rows.length>1)tbl.deleteRow(1);document.getElementById('fraudEmpty')?.classList.remove('hidden');updateFraudUI();}
function exportFraud(){let out="Rule,Severity,Evidence\n";fraudFlags.forEach(f=>out+='"'+f.name+'",'+f.sev+',"'+f.evidence+'"\n');dl(out,"FANTASTIC_fraud.csv","text/csv");}
let supAlerts=[],supBarges=0,supWhispers=0,supDurationFired=false;
function checkSupervisorTriggers(text,s,flags){if(document.getElementById('onFraud')?.checked){const thr=+document.getElementById('thrFraud').value;if(fraudScore>=thr&&!supAlerts.some(a=>a.trigger==='Fraud risk'))fireSupAlert('Fraud risk','Risk '+fraudScore+' ≥ '+thr,'critical');}if(document.getElementById('onNeg')?.checked){const thr=+document.getElementById('thrNeg').value;if(negStreak>=thr){fireSupAlert('Negative sentiment',negStreak+' negative turns','high');negStreak=0;}}if(document.getElementById('onEsc')?.checked&&/(supervisor|manager|human|escalate|tao)/i.test(text)){if(!supAlerts.some(a=>a.trigger==='Escalation request'))fireSupAlert('Escalation request','Customer asked for supervisor','high');}}
function checkDurationTrigger(el){if(!callActive||supDurationFired)return;if(!document.getElementById('onDur')?.checked)return;const thr=+document.getElementById('thrDur').value;if(el>=thr*60){supDurationFired=true;fireSupAlert('Long call','Exceeded '+thr+' min','med');}}
function fireSupAlert(trigger,detail,sev){supAlerts.push({trigger,detail,sev,time:new Date().toLocaleTimeString()});logSup(trigger,detail);const box=document.getElementById('supAlert');if(box){document.getElementById('supAlertMsg').textContent=' '+trigger+': '+detail;box.classList.add('show');}const si=document.getElementById('supStatusIcon');if(si){si.textContent=sev==='critical'?'🔴':sev==='high'?'🟠':'🟡';document.getElementById('supStatusText').textContent='Attention needed';}updateSupUI();}
function dismissSupAlert(){document.getElementById('supAlert').classList.remove('show');}
function supAction(mode){const banner=document.getElementById('supModeBanner');if(mode==='barge'){supBarges++;if(banner){banner.textContent='📞 SUPERVISOR BARGED IN';banner.classList.add('show');}addMsg('sup','🎧 Supervisor joined the call.');}else if(banner){banner.textContent=(mode==='monitor'?'👂 MONITORING':'🤫 WHISPER MODE')+' active';banner.classList.add('show');}const si=document.getElementById('supStatusIcon');if(si){si.textContent='🎧';document.getElementById('supStatusText').textContent=mode+' active';}updateSupUI();}
function sendWhisper(){const t=document.getElementById('whisperInput').value.trim();if(!t)return;supWhispers++;addMsg('sup','🤫 Whisper: '+t);document.getElementById('whisperInput').value='';updateSupUI();}
function logSup(tr,dt){const tbl=document.getElementById('supLog');if(!tbl)return;document.getElementById('supEmpty')?.classList.add('hidden');const r=tbl.insertRow(1);r.innerHTML='<td>'+new Date().toLocaleTimeString()+'</td><td>'+tr+'</td><td>'+dt+'</td><td>—</td>';}
function updateSupUI(){const t=document.getElementById('supTotal');if(!t)return;t.textContent=supAlerts.length;document.getElementById('supBarges').textContent=supBarges;document.getElementById('supWhispers').textContent=supWhispers;const mx=supAlerts.reduce((a,x)=>Math.max(a,sevRank(x.sev)),0);document.getElementById('supMax').textContent=mx===3?'🔴 Critical':mx===2?'🟠 High':mx===1?'🟡 Medium':'—';}
function resetSupervisor(){supAlerts=[];supBarges=0;supWhispers=0;supDurationFired=false;const tbl=document.getElementById('supLog');if(tbl)while(tbl.rows.length>1)tbl.deleteRow(1);document.getElementById('supEmpty')?.classList.remove('hidden');document.getElementById('supModeBanner')?.classList.remove('show');document.getElementById('supAlert')?.classList.remove('show');const si=document.getElementById('supStatusIcon');if(si){si.textContent='🟢';document.getElementById('supStatusText').textContent='Standing by';}updateSupUI();}
function agentSays(re){return convo.some(c=>c.role==='agent'&&re.test(c.text||''));}
function customerSays(re){return convo.some(c=>c.role==='customer'&&re.test((c.raw||c.text)||''));}
const ARROW_STEPS=[{id:'open',name:'Brand Opening',weight:12,crit:false,check:()=>agentSays(/(hello|hi|good|welcome|thank you for calling|salamat|magandang|kumusta|maayong|naimbag|maupay)/i)?'done':'miss'},{id:'rapport',name:'Active Listening',weight:12,crit:false,check:()=>{const q=convo.filter(c=>c.role==='agent'&&/\?|could you|tell me|pwede|paano|unsa|ano/i.test(c.text||'')).length;return q>=2?'done':q===1?'partial':'miss';}},{id:'verify',name:'Verification',weight:16,crit:true,check:()=>{const s=customerSays(/(account|refund|billing|charge|cancel|password)/i);const v=agentSays(/(verify|otp|account number|i-verify)/i);return !s?'done':v?'done':'miss';}},{id:'empathy',name:'Empathy & Apology',weight:14,crit:false,check:()=>{const e=agentSays(/(sorry|apolog|understand|pasensya|pasaylo|dispensar|nasabtan|nabatyagan|maawatak)/i)||convo.some(c=>c.empathized);if(sNeg===0)return e?'done':'partial';return e?'done':'miss';}},{id:'resolve',name:'Resolution',weight:18,crit:true,check:()=>{if(roleMode==='agent')return convo.filter(c=>c.kb).length>=1?'done':'miss';return agentSays(/(i(?:'| wi)ll|let me|i can|process|file|resolve|fix|refund|credit|gagawin|ayusin|tabang|bulig)/i)?'done':'miss';}},{id:'compliance',name:'Secure & Compliant',weight:16,crit:true,check:()=>fraudFlags.some(f=>f.sev==='critical')?'miss':fraudFlags.length?'partial':'done'},{id:'value',name:'Value-Add',weight:6,crit:false,check:()=>agentSays(/(upgrade|bundle|recommend|offer|would you like)/i)?'done':'miss'},{id:'close',name:'Proper Closing',weight:6,crit:false,check:()=>agentSays(/(anything else|glad to help|thank you for calling|may iba pa|paalam|salamat po|babay|agyaman)/i)||convo.some(c=>c.intent==='Closing')?'done':'miss'}];
function buildGapAnalysis(){let earned=0,total=0,done=0,miss=0,partial=0,crit=0;const rows=[];ARROW_STEPS.forEach(s=>{const st=s.check();total+=s.weight;if(st==='done'){earned+=s.weight;done++;}else if(st==='partial'){earned+=s.weight*0.5;partial++;}else{miss++;if(s.crit)crit++;}rows.push({s,st});});const pct=Math.round(earned/total*100);window._gapData={pct,rows};return pct;}
const AI_SYS="You are the live agent-assist SCRIPT WRITER for Inspiro/Infocom (PH BPO). From the transcript + KB, give the AGENT the single best next line + 1-2 alternatives. RULES: (1) reply in the customer's language — English, Tagalog, Cebuano, Hiligaynon, Ilokano, Waray, or Taglish. (2) If the customer is upset/reporting a problem, ALWAYS open with a sincere APOLOGY then EMPATHY before the solution. (3) Warm, concise, compliant (never collect card/OTP over voice). Format: 'SAY: <line>' then 'ALT: <a1> | <a2>' then 'TIP: <tip>'.";
const AI_SUM_SYS="You are a QA analyst. Summarize the call: 2-3 sentence overview then bullets 'Intent:', 'Resolution:', 'Sentiment:', 'Language:', 'Compliance:', 'Coaching:'. Under 150 words.";
let aiBusy=false,aiLastCall=0,aiTurnCount=0;
function convoForTarget(target){return target==='ac'?acConvo.map(c=>(c.speaker==='agent'?'Agent: ':'Customer: ')+c.text):convo.map(c=>((c.role==='agent'||c.who==='ai')?'Agent: ':'Customer: ')+c.text);}
function aiCtx(target){const turns=convoForTarget(target);const recent=turns.slice(-8).join('\n');const last=(target==='ac'?(acConvo[acConvo.length-1]||{}).text:(convo[convo.length-1]||{}).text)||'';const {best}=kbMatch(last||recent);const kb=best?('KB "'+best.q+'": '+best.a):'No specific KB match.';const langNote=target==='ac'?document.getElementById('acLang').selectedOptions[0].text:('detected '+langLabel(curLang));return 'Customer language: '+langNote+'\n\nRecent transcript:\n'+recent+'\n\nKnowledge base:\n'+kb+'\n\nWrite the next agent line in the customer\u2019s language.';}
async function callClaude(prompt,sys){if(!aiCfg.claudeKey)throw new Error('Claude: API key is empty. Paste your sk-ant-... key in Setup.');let res;try{res=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'x-api-key':aiCfg.claudeKey,'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true','content-type':'application/json'},body:JSON.stringify({model:aiCfg.claudeModel,max_tokens:600,system:sys||AI_SYS,messages:[{role:'user',content:prompt}]})});}catch(net){throw new Error('Claude: network/CORS error. Check your connection.');}if(!res.ok){let d='';try{const j=await res.json();d=(j.error&&(j.error.message||j.error.type))||'';}catch(e){}if(res.status===404)throw new Error('Claude 404 — model "'+aiCfg.claudeModel+'" not available on your key. Pick another model in Setup (e.g. Sonnet 4 or 3.5 Haiku).');if(res.status===401)throw new Error('Claude 401 — invalid API key. Copy a fresh sk-ant-… key from console.anthropic.com.');if(res.status===400)throw new Error('Claude 400 — '+(d||'bad request; usually an invalid model id.'));if(res.status===429)throw new Error('Claude 429 — rate limit or no credit balance on the key.');if(res.status===529)throw new Error('Claude 529 — Anthropic overloaded; try again shortly.');throw new Error('Claude '+res.status+' — '+d);}const dj=await res.json();return dj.content.map(x=>x.text).join('');}
function normalizeAzureEndpoint(ep){ep=(ep||'').trim();if(!ep)return '';if(!/^https?:\/\//i.test(ep))ep='https://'+ep;try{const u=new URL(ep);return u.protocol+'//'+u.host;}catch(e){return ep.replace(/\/openai\/.*/i,'').replace(/\/+$/,'').split('?')[0];}}
async function callCopilot(prompt,sys){const base=normalizeAzureEndpoint(aiCfg.copEndpoint);const deploy=(aiCfg.copDeploy||'').trim();const ver=(aiCfg.copVer||'2024-08-01-preview').trim();if(!base)throw new Error('Copilot: Endpoint empty. Use base url only.');if(!deploy)throw new Error('Copilot: Deployment name empty (Azure Foundry deployment, not model name).');if(!aiCfg.copKey)throw new Error('Copilot: API key empty.');const url=base+'/openai/deployments/'+encodeURIComponent(deploy)+'/chat/completions?api-version='+encodeURIComponent(ver);let res;try{res=await fetch(url,{method:'POST',headers:{'api-key':aiCfg.copKey,'content-type':'application/json'},body:JSON.stringify({messages:[{role:'system',content:sys||AI_SYS},{role:'user',content:prompt}],max_tokens:600,temperature:0.4})});}catch(net){throw new Error('Copilot: network/CORS error reaching '+base+'.');}if(!res.ok){let d='';try{const j=await res.json();d=(j.error&&(j.error.message||j.error.code))||JSON.stringify(j);}catch(e){try{d=await res.text();}catch(_){}}if(res.status===404)throw new Error('Copilot 404 — deployment "'+deploy+'" not found. Deployment must match EXACTLY your Azure Foundry deployment; endpoint = base url; api-version valid. Server: '+d);if(res.status===401)throw new Error('Copilot 401 — invalid key.');throw new Error('Copilot '+res.status+' — '+d);}const dj=await res.json();return dj.choices[0].message.content;}
async function callAI(prompt,sys){return aiCfg.provider==='copilot'?callCopilot(prompt,sys):callClaude(prompt,sys);}
function aiFormat(txt,target){const lines=txt.split('\n').filter(Boolean);let html='';window._lastSay=null;lines.forEach(l=>{const say=l.match(/^SAY:\s*(.*)/i),alt=l.match(/^ALT:\s*(.*)/i),tip=l.match(/^TIP:\s*(.*)/i);if(say){window._lastSay=say[1];html+=sugg(say[1],target,true);}else if(alt){alt[1].split('|').forEach(a=>{if(a.trim())html+=sugg(a.trim(),target,false);});}else if(tip)html+='<div class="note" style="margin-top:8px">🎓 '+tip[1]+'</div>';else html+='<div style="margin-top:6px">'+l+'</div>';});return html||('<div>'+txt+'</div>');}
function sugg(text,target,best){const t=text.replace(/"/g,'&quot;');return '<div class="ai-sugg"><span class="txt2">'+(best?'💬 <b>':'↪ ')+text+(best?'</b>':'')+'</span><button class="ai-ins" onclick="insertSuggestion(&quot;'+t+'&quot;)">➕ Insert</button></div>';}
function insertSuggestion(text){const b=document.getElementById('supModeBanner');if(b){b.textContent='🤫 AI WHISPER → Agent: '+text;b.classList.add('show');}addMsg('sup','🤖 AI suggestion inserted: '+text);if(!document.getElementById('agentconvo').classList.contains('hidden')){const inp=document.getElementById('acManual');if(inp){inp.value=text;}acInjectManual(true);}}
function guideBox(target){return document.getElementById(target==='ac'?'acAiGuide':'liveAiGuide');}
function kbGuide(target){const arr=target==='ac'?acConvo:convo;const last=(arr[arr.length-1]||{}).text||'';const {best,score}=kbMatch(last);const box=guideBox(target);if(!box)return;if(best&&score>0){box.innerHTML=sugg(best.a.split('.')[0]+'.',target,true)+'<div class="note" style="margin-top:6px">📌 KB: '+best.q+'</div>';window._lastSay=best.a.split('.')[0]+'.';}else{box.innerHTML=sugg('Acknowledge, apologize if needed, empathize, then ask a clarifying question.',target,true)+'<div class="note" style="margin-top:6px">Built-in KB guidance (connect Claude for full multilingual script).</div>';window._lastSay='Acknowledge, empathize, and ask a clarifying question.';}maybeAutoInsert(target);}
function maybeAutoInsert(target){if(target==='ac'&&document.getElementById('autoInsert')?.checked&&window._lastSay)insertSuggestion(window._lastSay);}
async function aiGuide(target,force){target=target||(document.getElementById('agentconvo').classList.contains('hidden')?'live':'ac');if(!force){if(!aiCfg.auto)return;aiTurnCount++;if(aiTurnCount%2!==0)return;if(Date.now()-aiLastCall<5000)return;}if(aiCfg.provider==='kb'){kbGuide(target);return;}if(aiBusy)return;const box=guideBox(target);if(!box)return;aiBusy=true;aiLastCall=Date.now();box.innerHTML='<span class="thinking"><span class="spin"></span> '+(aiCfg.provider==='claude'?'Claude':'Copilot')+' is writing the script…</span>';try{const txt=await callAI(aiCtx(target),AI_SYS);box.innerHTML=aiFormat(txt,target);maybeAutoInsert(target);}catch(e){box.innerHTML='<div class="conn err" style="display:block">⚠️ '+e.message+' — using KB.</div>';kbGuide(target);}finally{aiBusy=false;}}
function liveAiGuide(){aiGuide('live');}
function aiGuideManual(){aiGuide('ac',true);}
async function aiDraftSummary(target){const box=document.getElementById(target==='ac'?'acSummary':null);const arr=target==='ac'?acConvo:convo;if(!arr.length){if(box)box.innerHTML='<div class="note">No conversation yet.</div>';return;}const transcript=convoForTarget(target).join('\n');if(aiCfg.provider==='kb'||!(aiCfg.provider==='claude'?aiCfg.claudeKey:aiCfg.copKey)){const dom=sNeg>=sPos&&sNeg>=sNeu?'Negative':sPos>=sNeu?'Positive':'Neutral';const kbHits=arr.filter(c=>c.kb).length;const txt='Call handled over '+arr.length+' turns. Intent: '+((arr.find(c=>c.intent&&!['Greeting','Closing'].includes(c.intent))||{}).intent||'general')+'. Resolution: '+(kbHits>0?'KB-based answer provided':'follow-up needed')+'. Sentiment: '+dom+'. Language: '+langLabel(curLang)+'. Compliance: '+(fraudFlags.some(f=>f.sev==='critical')?'⚠️ critical flag':'clean')+'. Coaching: '+(dom==='Negative'?'apologize & empathize sooner':'maintain strong rapport')+'.';window._aiSummary=txt;if(box)box.innerHTML='<div class="ai-guide-box">'+txt+'</div><div class="note">Built-in summary (connect Claude for richer drafts).</div>';return txt;}if(box)box.innerHTML='<span class="thinking"><span class="spin"></span> Drafting summary…</span>';try{const txt=await callAI('Transcript:\n'+transcript,AI_SUM_SYS);window._aiSummary=txt;if(box)box.innerHTML='<div class="ai-guide-box">'+txt.replace(/\n/g,'<br>')+'</div><div class="ai-badge '+aiCfg.provider+'" style="margin-top:8px">'+(aiCfg.provider==='claude'?'Claude':'Copilot')+'-drafted</div>';return txt;}catch(e){if(box)box.innerHTML='<div class="conn err" style="display:block">⚠️ '+e.message+'</div>';}}
function setAIProvider(p){aiCfg.provider=p;saveAICfg();['KB','Claude','Copilot'].forEach(x=>{const id=x.toLowerCase();document.getElementById('prov'+x)?.classList.toggle('on',id===p);document.getElementById('setProv'+x)?.classList.toggle('on',id===p);});const lab=p==='claude'?'CLAUDE':p==='copilot'?'COPILOT':'KB';['acAiBadge','liveAiBadge'].forEach(id=>{const b=document.getElementById(id);if(b){b.textContent=lab;b.className='ai-badge '+p;}});}
async function testAI(p){const c=document.getElementById(p==='claude'?'claudeConn':'copilotConn');syncAICfgFromInputs();if(p==='claude'&&!aiCfg.claudeKey){c.className='conn err';c.textContent='⚠️ Paste your Anthropic key.';return;}if(p==='copilot'&&(!aiCfg.copEndpoint||!aiCfg.copKey)){c.className='conn err';c.textContent='⚠️ Enter endpoint + key + deployment.';return;}c.className='conn wait';c.textContent='⏳ Testing…';try{const txt=await(p==='claude'?callClaude('Reply with exactly: connection ok'):callCopilot('Reply with exactly: connection ok'));c.className='conn ok';c.textContent='✅ Connected: '+txt.slice(0,70);setAIProvider(p);logAudit('AI provider tested',p+' OK','config');}catch(e){c.className='conn err';c.textContent='❌ '+e.message;}}
async function testBothAI(){const cur=aiCfg.provider||'kb';try{await testAI('claude');}catch(e){}await new Promise(r=>setTimeout(r,300));try{await testAI('copilot');}catch(e){}setAIProvider(cur);}
function syncAICfgFromInputs(){aiCfg.claudeKey=document.getElementById('claudeKey').value.trim();aiCfg.claudeModel=document.getElementById('claudeModel').value;aiCfg.copEndpoint=document.getElementById('copilotEndpoint').value.trim();aiCfg.copKey=document.getElementById('copilotKey').value.trim();aiCfg.copDeploy=document.getElementById('copilotDeploy').value.trim()||'gpt-4o';aiCfg.copVer=document.getElementById('copilotVer').value.trim()||'2024-08-01-preview';aiCfg.auto=document.getElementById('aiAutoGuide').checked;aiCfg.autoSummary=document.getElementById('aiAutoSummary').checked;saveAICfg();}
let aiCfg={provider:'claude',claudeKey:'',claudeModel:'claude-opus-4-1-20250805',copEndpoint:'',copKey:'',copDeploy:'gpt-4o',copVer:'2024-08-01-preview',auto:true,autoSummary:true};
function loadAICfg(){try{Object.assign(aiCfg,JSON.parse(localStorage.getItem('ft_ai')||'{}'));}catch(e){}if(aiCfg.claudeModel==='claude-opus-5'||!aiCfg.claudeModel)aiCfg.claudeModel='claude-opus-4-1-20250805';}
function saveAICfg(){store('ft_ai',aiCfg);}
loadAICfg();
let acActive=false,acRec=null,acAz=null,acAzRunning=false,acInterim=null,acConvo=[],acStream=null,acNextSpeaker='auto',acLastSpeaker='customer',acStartTime=0,acTurnStart=0;
let acSysCtx=null,acSysNode=null,acSysGain=null,acSysRec=null,acSysRunning=false,acSysInterim=null,acPush=null;
let mixCtx=null,mixDest=null,mixRec=null,mixChunks=[],acMicStream=null,mixURL=null;
const acTEl=document.getElementById('acTranscript');
const AGENT_CUES=/(thank you for calling|salamat sa pagtawag|how may i|how can i help|let me|i'll|i will|verify|i-verify|one moment|please hold|is there anything else|may iba pa|glad to help|i apologize|let me check|welcome to|gagawin ko|tabang|bulig)/i;
const CUST_CUES=/(my bill|my account|i want|i need|why is|how do i|can you|i was charged|ang bill ko|gusto ko|kailangan ko|bakit|refund|complaint|reklamo|ngano|ngaa|unsa|ano)/i;
function classifySpeaker(text){if(acNextSpeaker!=='auto'){const s=acNextSpeaker;acNextSpeaker='auto';syncDiaButtons();return s;}const t=text.toLowerCase();let a=(t.match(AGENT_CUES)||[]).length,c=(t.match(CUST_CUES)||[]).length;if(/\?$/.test(text.trim()))c+=0.5;let spk;if(a>c)spk='agent';else if(c>a)spk='customer';else spk=(acLastSpeaker==='agent')?'customer':'agent';acLastSpeaker=spk;return spk;}
function setNextSpeaker(m){acNextSpeaker=m;syncDiaButtons();}
function syncDiaButtons(){document.getElementById('diaAgent').classList.toggle('on',acNextSpeaker==='agent');document.getElementById('diaCust').classList.toggle('on',acNextSpeaker==='customer');document.getElementById('diaAuto').classList.toggle('on',acNextSpeaker==='auto');}
function acAddMsg(text,interim,speaker){document.getElementById('acEmptyT')?.remove();const dia=document.getElementById('acDiaOn')?.checked;const spk=speaker||'customer';const cls=(dia&&spk==='agent')?'ai':(spk==='system'?'sys':'cust');const m=document.createElement('div');m.className='msg '+cls+(interim?' interim':'');if(interim){m.innerHTML='<div class="who">Transcribing…</div><span class="txt">'+text+'</span>';}else if(dia){const lbl=spk==='agent'?'🎧 Agent':spk==='system'?'🔊 Customer (system audio)':'🧑 Customer';m.innerHTML='<div class="who">'+lbl+'<span class="spk-flip" onclick="flipSpeaker(this)">⇄</span></div><span class="txt">'+text+'</span>';m.dataset.spk=(spk==='agent'?'agent':'customer');}else{m.innerHTML='<div class="who">Live caller</div><span class="txt">'+text+'</span>';}acTEl.appendChild(m);acTEl.scrollTop=acTEl.scrollHeight;return m;}
function flipSpeaker(el){const m=el.closest('.msg');const idx=[...acTEl.querySelectorAll('.msg:not(.interim)')].indexOf(m);const next=m.dataset.spk==='agent'?'customer':'agent';m.dataset.spk=next;m.className='msg '+(next==='agent'?'ai':'cust');m.querySelector('.who').innerHTML=(next==='agent'?'🎧 Agent':'🧑 Customer')+'<span class="spk-flip" onclick="flipSpeaker(this)">⇄</span>';if(acConvo[idx])acConvo[idx].speaker=next;acUpdateChecklist();acRenderTalkTime();acRenderTimeline();}
function acStartRec(){if(!acActive)return;if(sttMode==='azure'&&azureCfg.key&&window.SpeechSDK){acStartAzure();return;}if(!SR){const t=document.getElementById('acTranscript');if(t){const d=document.createElement('div');d.className='note';d.style.color='var(--red)';d.innerHTML='⚠️ No browser speech recognition. Use Chrome/Edge or enable Azure STT.';t.appendChild(d);}return;}try{if(acRec)acRec.abort();}catch(e){}try{acRec=new SR();acRec.continuous=false;acRec.interimResults=true;acRec.lang=(document.getElementById('acLang')||{}).value||'en-US';acRec.onresult=e=>{let interim="",final="";for(let i=e.resultIndex;i<e.results.length;i++){const tr=e.results[i][0].transcript;if(e.results[i].isFinal)final+=tr;else interim+=tr;}if(interim){if(!acInterim)acInterim=acAddMsg("",true);acInterim.querySelector('.txt').textContent=interim;}if(final){if(acInterim){acInterim.remove();acInterim=null;}acNextSpeaker='agent';acHandle(final.trim());}};acRec.onend=()=>{if(acActive&&sttMode!=='azure')setTimeout(acStartRec,300);};acRec.onerror=ev=>{if(ev&&(ev.error==='not-allowed'||ev.error==='service-not-allowed')){const t=document.getElementById('acTranscript');if(t){const d=document.createElement('div');d.className='note';d.style.color='var(--red)';d.innerHTML='🎙️ Mic blocked. Allow it via the padlock, then press Start.';t.appendChild(d);}}};acRec.start();}catch(e){setTimeout(()=>{try{acRec&&acRec.start();}catch(_){}} ,400);}}
function acAzAudio(){return window.ftMicId?SpeechSDK.AudioConfig.fromMicrophoneInput(window.ftMicId):SpeechSDK.AudioConfig.fromDefaultMicrophoneInput();}
function acStartAzure(){if(acAzRunning)return;try{const cfg=SpeechSDK.SpeechConfig.fromSubscription(azureCfg.key,azureCfg.region);cfg.speechRecognitionLanguage=document.getElementById('acLang').value;acAz=new SpeechSDK.SpeechRecognizer(cfg,acAzAudio());acAz.recognizing=(s,e)=>{const t=e.result.text;if(!t)return;if(!acInterim)acInterim=acAddMsg("",true);acInterim.querySelector('.txt').textContent=t;};acAz.recognized=(s,e)=>{if(e.result.reason===SpeechSDK.ResultReason.RecognizedSpeech){if(acInterim){acInterim.remove();acInterim=null;}const t=e.result.text.trim();if(t){acNextSpeaker='agent';acHandle(t);}}};acAz.canceled=()=>{acAzRunning=false;};acAz.startContinuousRecognitionAsync(()=>{acAzRunning=true;},()=>{acAzRunning=false;});}catch(e){}}
function acStopRec(){try{acRec&&acRec.abort();}catch(e){}if(acAz&&acAzRunning){try{acAz.stopContinuousRecognitionAsync(()=>{try{acAz.close();}catch(e){}acAz=null;acAzRunning=false;});}catch(e){acAzRunning=false;}}}
const acLangSel=document.getElementById('acLang');if(acLangSel)acLangSel.addEventListener('change',()=>{if(acActive&&sttMode==='browser'){try{acRec&&acRec.abort();}catch(e){}}});
function startSysAudio(stream){const at=stream.getAudioTracks();if(!at.length)return false;document.getElementById('acSysInd').classList.remove('hidden');if(!(sttMode==='azure'&&azureCfg.key&&window.SpeechSDK))return true;try{const fmt=SpeechSDK.AudioStreamFormat.getWaveFormatPCM(16000,16,1);acPush=SpeechSDK.AudioInputStream.createPushStream(fmt);const cfg=SpeechSDK.SpeechConfig.fromSubscription(azureCfg.key,azureCfg.region);cfg.speechRecognitionLanguage=document.getElementById('acLang').value;acSysRec=new SpeechSDK.SpeechRecognizer(cfg,SpeechSDK.AudioConfig.fromStreamInput(acPush));acSysRec.recognizing=(s,e)=>{const t=e.result.text;if(!t)return;if(!acSysInterim)acSysInterim=acAddMsg('',true,'system');acSysInterim.querySelector('.txt').textContent=t;};acSysRec.recognized=(s,e)=>{if(e.result.reason===SpeechSDK.ResultReason.RecognizedSpeech){if(acSysInterim){acSysInterim.remove();acSysInterim=null;}const t=e.result.text.trim();if(t){acNextSpeaker='customer';acHandle(t,'system');}}};acSysRec.startContinuousRecognitionAsync(()=>{acSysRunning=true;},()=>{});acSysCtx=new (window.AudioContext||window.webkitAudioContext)({sampleRate:16000});const src=acSysCtx.createMediaStreamSource(new MediaStream(at));acSysNode=acSysCtx.createScriptProcessor(4096,1,1);acSysGain=acSysCtx.createGain();acSysGain.gain.value=0;src.connect(acSysNode);acSysNode.connect(acSysGain);acSysGain.connect(acSysCtx.destination);acSysNode.onaudioprocess=ev=>{const f=ev.inputBuffer.getChannelData(0);const buf=new ArrayBuffer(f.length*2);const dv=new DataView(buf);for(let i=0;i<f.length;i++){let x=Math.max(-1,Math.min(1,f[i]));dv.setInt16(i*2,x<0?x*0x8000:x*0x7FFF,true);}acPush.write(buf);};return true;}catch(e){console.warn('sys',e);return true;}}
function stopSysAudio(){try{if(acSysNode){acSysNode.disconnect();acSysNode=null;}if(acSysGain){acSysGain.disconnect();acSysGain=null;}if(acSysCtx){acSysCtx.close();acSysCtx=null;}if(acPush){try{acPush.close();}catch(e){}acPush=null;}if(acSysRec&&acSysRunning){acSysRec.stopContinuousRecognitionAsync(()=>{try{acSysRec.close();}catch(e){}acSysRec=null;acSysRunning=false;});}}catch(e){}document.getElementById('acSysInd')?.classList.add('hidden');}
async function startMixRecording(){try{if(mixRec)return;if(!window.MediaRecorder)return;mixCtx=new (window.AudioContext||window.webkitAudioContext)();mixDest=mixCtx.createMediaStreamDestination();try{acMicStream=await navigator.mediaDevices.getUserMedia(window.ftMicConstraint());mixCtx.createMediaStreamSource(acMicStream).connect(mixDest);}catch(e){try{acMicStream=await navigator.mediaDevices.getUserMedia({audio:true});mixCtx.createMediaStreamSource(acMicStream).connect(mixDest);}catch(_){}}try{if(acStream&&acStream.getAudioTracks().length)mixCtx.createMediaStreamSource(new MediaStream(acStream.getAudioTracks())).connect(mixDest);}catch(e){}let mime='';['audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus','audio/ogg'].forEach(m=>{if(!mime&&MediaRecorder.isTypeSupported(m))mime=m;});mixRec=new MediaRecorder(mixDest.stream,mime?{mimeType:mime}:undefined);mixChunks=[];mixRec.ondataavailable=e=>{if(e.data&&e.data.size)mixChunks.push(e.data);};mixRec.start(1000);const b=document.getElementById('acDlRec');if(b)b.style.display='none';const s=document.getElementById('acRecInd');if(s)s.style.display='';}catch(e){console.warn('mix',e);}}
function addSysToMix(){try{if(mixCtx&&mixDest&&acStream&&acStream.getAudioTracks().length)mixCtx.createMediaStreamSource(new MediaStream(acStream.getAudioTracks())).connect(mixDest);}catch(e){}}
function stopMixRecording(){if(!mixRec)return;try{mixRec.onstop=()=>{const type=(mixChunks[0]&&mixChunks[0].type)||'audio/webm';const blob=new Blob(mixChunks,{type});if(mixURL){try{URL.revokeObjectURL(mixURL);}catch(e){}}mixURL=URL.createObjectURL(blob);const ext=type.indexOf('ogg')>=0?'ogg':'webm';const fn='FANTASTIC_recording_'+new Date().toISOString().replace(/[:.]/g,'-')+'.'+ext;const kb=Math.round(blob.size/1024);const b=document.getElementById('acDlRec');if(b){b.style.display='';b.textContent='⬇️ Download recording ('+kb+' KB · mic + system)';b.onclick=()=>{const a=document.createElement('a');a.href=mixURL;a.download=fn;a.click();try{logAudit('Downloaded recording',fn,'data');}catch(e){}};}const s=document.getElementById('acRecInd');if(s)s.style.display='none';try{acMicStream&&acMicStream.getTracks().forEach(t=>t.stop());}catch(e){}try{mixCtx&&mixCtx.close();}catch(e){}mixCtx=null;mixDest=null;mixRec=null;};mixRec.stop();}catch(e){console.warn('stopmix',e);}}
async function acShareScreen(){const prev=document.getElementById('acSharePrev');if(!acActive){await acToggle();}try{acStream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:true});prev.innerHTML='<video autoplay muted></video>';const v=prev.querySelector('video');v.srcObject=acStream;acStream.getVideoTracks()[0].onended=()=>{stopSysAudio();prev.innerHTML='<span>Screen share ended.</span>';document.getElementById('acShareNote').textContent='';};const hasAudio=startSysAudio(acStream);addSysToMix();const note=document.getElementById('acShareNote');if(hasAudio){note.innerHTML='🔊 <b>System audio captured</b>'+((sttMode==='azure'&&azureCfg.key)?' — transcribing customer side via Azure STT.':' — enable <b>Azure STT</b> to transcribe it.');}else{note.innerHTML='⚠️ <b>No system audio.</b> Pick a <b>Chrome Tab</b> and tick <b>Share tab audio</b>, then Share again.';}}catch(e){document.getElementById('acShareMsg').textContent='Screen share cancelled or blocked.';}}
function acHandle(text,src){const spk=classifySpeaker(text);const now=Date.now();const dur=acTurnStart?(now-acTurnStart)/1000:2;const words=text.trim().split(/\s+/).length;const prev=acConvo[acConvo.length-1];const interrupted=prev&&prev.speaker!==spk&&dur<1.2;acConvo.push({speaker:spk,text,words,dur:Math.max(0.5,dur),interrupted,src:src||'mic'});acTurnStart=now;acAddMsg(text,false,src==='system'?'system':spk);acUpdateChecklist();acRenderTalkTime();acRenderTimeline();aiGuide('ac');}
function acInjectManual(fromAI){const inp=document.getElementById('acManual');const text=inp.value.trim();if(!text)return;acNextSpeaker='agent';acHandle(text);inp.value='';}
function acJoined(){return acConvo.map(c=>c.text).join(' ');}
function acAgentText(){return acConvo.filter(c=>c.speaker==='agent').map(c=>c.text).join(' ');}
function acRenderTalkTime(){const el=document.getElementById('acTalkTime');if(!el)return;const ag=acConvo.filter(c=>c.speaker==='agent'),cu=acConvo.filter(c=>c.speaker==='customer');const aw=ag.reduce((s,c)=>s+(c.words||0),0),cw=cu.reduce((s,c)=>s+(c.words||0),0),tw=aw+cw||1;const aPct=Math.round(aw/tw*100),cPct=100-aPct;const interr=acConvo.filter(c=>c.interrupted).length;const sys=acConvo.filter(c=>c.src==='system').length;el.innerHTML='<div class="tt-wrap"><div class="tt-a" style="width:'+Math.max(6,aPct)+'%">🎧 '+aPct+'%</div><div class="tt-c" style="width:'+Math.max(6,cPct)+'%">🧑 '+cPct+'%</div></div><div class="sum-line"><b>🎧 Agent (mic)</b><span>'+ag.length+' turns · '+aw+' words</span></div><div class="sum-line"><b>🧑 Customer</b><span>'+cu.length+' turns · '+cw+' words</span></div><div class="sum-line"><b>🔊 From system audio</b><span>'+sys+' turns</span></div><div class="sum-line"><b>Interruptions</b><span>'+interr+'</span></div>';window._acTalk={aPct,cPct,agTurns:ag.length,cuTurns:cu.length,interr,sys};}
function acRenderTimeline(){const el=document.getElementById('acTimeline');if(!el||!acConvo.length)return;const total=acConvo.reduce((s,c)=>s+(c.dur||1),0)||1;function segs(role){return acConvo.map(c=>{const w=(c.dur||1)/total*100;if(c.speaker!==role)return '<div class="tl-seg" style="width:'+w+'%;background:transparent"></div>';return '<div class="tl-seg '+(c.interrupted?'overtalk':role)+'" style="width:'+w+'%" title="'+role+': '+(c.words||0)+'w">'+(c.interrupted?'<span class="tl-mark">🔴</span>':'')+'</div>';}).join('');}const interr=acConvo.filter(c=>c.interrupted).length;el.innerHTML='<div class="tl-wrap"><div class="tl-row"><div class="tl-lab">🎧 Agent</div><div class="tl-track">'+segs('agent')+'</div></div><div class="tl-row"><div class="tl-lab">🧑 Customer</div><div class="tl-track">'+segs('customer')+'</div></div></div><div class="tl-legend"><span><i style="background:var(--teal)"></i>Agent</span><span><i style="background:#475569"></i>Customer</span><span><i style="background:#dc2626"></i>🔴 Overtalk</span></div><div class="note">'+acConvo.length+' turns · '+interr+' interruptions.</div>';}
async function acToggle(){const btn=document.getElementById('acStart');if(!acActive){if(!SR&&sttMode==='browser'){alert("Needs Chrome/Edge or Azure STT.");return;}await ensureMic();acActive=true;acConvo=[];acTEl.innerHTML="";acNextSpeaker='auto';acLastSpeaker='customer';acStartTime=Date.now();acTurnStart=0;syncDiaButtons();document.getElementById('acMicInd').classList.remove('hidden');btn.textContent='⏹️ Stop';btn.style.background='var(--red)';acStartRec();acRenderChecklist();startMixRecording();}else{acActive=false;acStopRec();document.getElementById('acMicInd').classList.add('hidden');btn.textContent='🎙️ Start';btn.style.background='';if(acConvo.length)acEndSession(true);}}
const AC_CHECKS=[{id:'greet',label:'Branded greeting',re:/(hello|hi|good|welcome|thank you for calling|salamat|magandang|buenos|kumusta|maayong|naimbag|maupay)/i},{id:'empathy',label:'Empathy / Apology',re:/(sorry|apolog|understand|pasensya|pasaylo|lo siento|nasabtan|nabatyagan|dispensar)/i},{id:'verify',label:'Identity verification',re:/(verify|otp|account number|i-verify|verificar)/i},{id:'resolve',label:'Resolution',re:/(i'll|let me|i can|process|file|resolve|fix|refund|credit|gagawin|ayusin|tabang|bulig)/i},{id:'close',label:'Proper closing',re:/(anything else|glad to help|thank you for calling|salamat po|algo m[aá]s|paalam|babay|agyaman)/i},{id:'compliance',label:'No sensitive data exposed',re:null}];
function acRenderChecklist(){const el=document.getElementById('acChecklist');if(el)el.innerHTML=AC_CHECKS.map(c=>'<div class="check-item" id="ac_'+c.id+'"><div class="cx">○</div><div>'+c.label+'</div></div>').join('');document.getElementById('acLiveScore').textContent='0%';}
function acUpdateChecklist(){const dia=document.getElementById('acDiaOn')?.checked;const full=acJoined();const ao=acAgentText();let pass=0;AC_CHECKS.forEach(c=>{let ok;if(c.id==='compliance')ok=!FRAUD_RULES.slice(0,3).some(r=>r.test(full));else ok=c.re.test((dia&&ao)?ao:full);const row=document.getElementById('ac_'+c.id);if(!row)return;row.className='check-item '+(ok?'pass':'');row.querySelector('.cx').textContent=ok?'✓':'○';if(ok)pass++;});document.getElementById('acLiveScore').textContent=Math.round(pass/AC_CHECKS.length*100)+'%';}
function acUseLive(){const dia=document.getElementById('acDiaOn')?.checked;document.getElementById('acTaInput').value=acConvo.map(c=>dia?((c.speaker==='agent'?'Agent: ':'Customer: ')+c.text):c.text).join('\n');}
function acEvalTranscript(){const raw=document.getElementById('acTaInput').value.trim();if(!raw){alert('Paste a transcript first.');return 0;}const full=raw.toLowerCase();let earned=0,total=0;const rows=[];AC_CHECKS.forEach(c=>{const w=c.id==='resolve'?25:(c.id==='verify'||c.id==='compliance')?20:c.id==='empathy'?15:10;total+=w;let ok=c.id==='compliance'?!FRAUD_RULES.slice(0,3).some(r=>r.test(raw)):c.re.test(full);if(ok)earned+=w;rows.push({label:c.label,ok,w});});const pct=Math.round(earned/total*100);document.getElementById('acEvalResult').innerHTML='<div style="font-size:30px;font-weight:800;color:'+(pct>=85?'var(--green)':pct>=70?'var(--amber)':'var(--red)')+'">'+pct+'<span style="font-size:15px">/100</span></div>'+rows.map(r=>'<div class="check-item '+(r.ok?'pass':'fail')+'"><div class="cx">'+(r.ok?'✓':'✕')+'</div><div>'+r.label+'</div><span style="margin-left:auto;font-weight:700">'+(r.ok?r.w:0)+'/'+r.w+'</span></div>').join('');return pct;}
function acEndSession(silent){if(acActive){acActive=false;acStopRec();document.getElementById('acMicInd').classList.add('hidden');const b=document.getElementById('acStart');b.textContent='🎙️ Start';b.style.background='';}stopSysAudio();stopMixRecording();const name=(document.getElementById('acAgentName').value||'Live Agent').trim();const aid=(document.getElementById('acAgentId').value||'').trim();acUseLive();const score=acEvalTranscript()||0;const tt=window._acTalk||{};const ag=findAgent(name,aid);const rec={id:'INT-'+Date.now(),date:new Date().toISOString(),mode:'Live Agent Convo (diarized)',agent:ag?(ag.first+' '+ag.last):name,agentId:aid||(ag?ag.emp:''),site:ag?ag.site:'',bu:ag?ag.bu:'',section:ag?ag.section:'',sub:ag?ag.sub:'',lang:document.getElementById('acLang').selectedOptions[0].text,durationSec:acStartTime?Math.floor((Date.now()-acStartTime)/1000):0,turns:acConvo.length,sentiment:{pos:0,neu:tt.cuTurns||0,neg:0,dom:'Neutral'},fraudScore:0,gapPct:score,resolved:score>=70,talkTime:tt,interruptions:acConvo.filter(c=>c.interrupted).length,transcript:acConvo.map(c=>({role:c.speaker,who:c.speaker==='agent'?'ai':'cust',text:c.text}))};const arr=loadInteractions();arr.unshift(rec);saveInteractionsArr(arr);renderLibrary();awardPoints(name,{quality:score,training:0,tag:'Live agent session',agentId:aid});if(aiCfg.autoSummary)aiDraftSummary('ac');const msg=document.createElement('div');msg.className='conn ok';msg.style.marginTop='10px';msg.textContent='✅ Saved & posted '+score+'/100'+(ag?' · '+ag.site+'/'+ag.bu:'')+'. Recording ready in the Screen-Share card.';document.getElementById('acEvalResult').prepend(msg);if(!silent)alert('✅ Session for '+name+': '+score+'/100 saved & posted!');}
function loadAgents(){return read('ft_agents',[]);}
function saveAgents(a){store('ft_agents',a);}
function addOption(sel,label){const v=prompt('Add new '+label+':');if(!v)return;const o=document.createElement('option');o.value=v;o.textContent=v;sel.insertBefore(o,sel.querySelector('option[value="__add"]'));sel.value=v;}
['agSite','agBU','agSection','agSub'].forEach(id=>{const el=document.getElementById(id);if(el)el.addEventListener('change',function(){if(this.value==='__add'){this.value=this.options[0].value;addOption(this,id);}});});
function saveAgent(){const emp=document.getElementById('agEmp').value.trim();const first=document.getElementById('agFirst').value.trim();const last=document.getElementById('agLast').value.trim();const msg=document.getElementById('agMsg');if(!emp||!first){msg.style.color='var(--red)';msg.textContent='⚠️ Employee # and First Name required.';return;}const rec={emp,first,last,site:document.getElementById('agSite').value,bu:document.getElementById('agBU').value,section:document.getElementById('agSection').value,sub:document.getElementById('agSub').value};const arr=loadAgents();const i=arr.findIndex(a=>a.emp===emp);if(i>=0)arr[i]=rec;else arr.push(rec);saveAgents(arr);clearAgentForm();msg.style.color='var(--green)';msg.textContent='✅ Saved.';renderAgents();populateLbSites();logAudit('Agent saved',emp,'agent');setTimeout(()=>msg.textContent='',3000);}
function clearAgentForm(){['agEmp','agFirst','agLast'].forEach(id=>document.getElementById(id).value='');}
function renderAgents(f){f=f||document.getElementById('agSearch')?.value||'';const arr=loadAgents();const tbl=document.getElementById('agTable');if(!tbl)return;while(tbl.rows.length>1)tbl.deleteRow(1);document.getElementById('agCount').textContent=arr.length;document.getElementById('agEmpty').style.display=arr.length?'none':'block';arr.filter(a=>(a.emp+a.first+a.last+a.site+a.bu).toLowerCase().includes(f.toLowerCase())).forEach(a=>{const r=tbl.insertRow(-1);r.innerHTML='<td>'+a.emp+'</td><td>'+a.first+' '+a.last+'</td><td>'+a.site+'</td><td>'+a.bu+'</td><td>'+a.section+'</td><td>'+a.sub+'</td><td><button style="font-size:11px;color:var(--red);background:none;border:none;cursor:pointer" onclick="delAgent(\''+a.emp+'\')">🗑</button></td>';});}
function delAgent(emp){if(!confirm('Delete '+emp+'?'))return;saveAgents(loadAgents().filter(a=>a.emp!==emp));renderAgents();populateLbSites();logAudit('Agent deleted',emp,'agent');}
function findAgent(name,id){const arr=loadAgents();if(id){const m=arr.find(a=>a.emp.toLowerCase()===String(id).toLowerCase());if(m)return m;}const nm=(name||'').toLowerCase().trim();if(!nm)return null;return arr.find(a=>((a.first+' '+a.last).toLowerCase()===nm)||a.first.toLowerCase()===nm);}
const agSearchEl=document.getElementById('agSearch');if(agSearchEl)agSearchEl.oninput=e=>renderAgents(e.target.value);
function exportAgents(){let out="Employee #,First Name,Last Name,Site,BU,Section,Sub-section\n";loadAgents().forEach(a=>out+=[a.emp,a.first,a.last,a.site,a.bu,a.section,a.sub].map(csvEsc).join(',')+'\n');dl(out,"FANTASTIC_agents.csv","text/csv");logAudit('Exported agents','','export');}
function importAgents(ev){const f=ev.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const rows=parseCSV(r.result);const arr=loadAgents();let n=0;for(let i=1;i<rows.length;i++){const [emp,first,last,site,bu,section,sub]=rows[i];if(!emp)continue;const rec={emp,first:first||'',last:last||'',site:site||'Manila',bu:bu||'Infocom',section:section||'',sub:sub||''};const j=arr.findIndex(a=>a.emp===emp);if(j>=0)arr[j]=rec;else arr.push(rec);n++;}saveAgents(arr);renderAgents();populateLbSites();logAudit('Imported agents',n+' rows','agent');alert('✅ Imported '+n+'.');};r.readAsText(f);ev.target.value='';}
function seedAgents(){const s=[['EMP-1001','Juan','Dela Cruz','Manila','Infocom','PLDT','Billing'],['EMP-1002','Maria','Santos','Pasig','JAPAC','Smart','Repair'],['EMP-1003','Jose','Reyes','Makati','International','PNB','Prepaid'],['EMP-1004','Ana','Lopez','Dumaguete','Infocom','PLDT','Repair'],['EMP-1005','Pedro','Garcia','Circuit','Dish','Smart','Billing'],['EMP-1006','Rosa','Fernandez','Nicaragua','International','PNB','Billing'],['EMP-1007','Mark','Villanueva','Manila','JAPAC','Smart','Prepaid'],['EMP-1008','Grace','Torres','Pasig','Infocom','PLDT','Billing']];const arr=loadAgents();s.forEach(x=>{if(!arr.find(a=>a.emp===x[0]))arr.push({emp:x[0],first:x[1],last:x[2],site:x[3],bu:x[4],section:x[5],sub:x[6]});});saveAgents(arr);renderAgents();populateLbSites();logAudit('Loaded sample roster','','agent');alert('✅ Sample roster loaded.');}
function loadBatch(){return read('ft_batch',[]);}
function saveBatch(a){store('ft_batch',a);}
function batchLookup(){const id=document.getElementById('bAgentId').value.trim();const m=document.getElementById('bMatch');const ag=findAgent(document.getElementById('bAgent').value.trim(),id);if(ag){m.className='conn ok';m.textContent='✅ Matched: '+ag.first+' '+ag.last+' · '+ag.site+' · '+ag.bu;if(!document.getElementById('bAgent').value)document.getElementById('bAgent').value=ag.first+' '+ag.last;}else if(id){m.className='conn wait';m.textContent='⚠️ No match for "'+id+'".';}else{m.className='';m.textContent='';}}
function parseConvo(text){return text.split(/\||\n/).map(l=>l.trim()).filter(Boolean).map(l=>{const mm=l.match(/^(agent|customer|cust|caller)\s*[:\-]\s*(.*)$/i);if(mm){const spk=/^a/i.test(mm[1])?'agent':'customer';return {speaker:spk,text:mm[2],who:spk==='agent'?'ai':'cust'};}return {speaker:'customer',text:l,who:'cust'};});}
function evalConvoText(raw){const full=raw.toLowerCase();let earned=0,total=0;AC_CHECKS.forEach(c=>{const w=c.id==='resolve'?25:(c.id==='verify'||c.id==='compliance')?20:c.id==='empathy'?15:10;total+=w;let ok=c.id==='compliance'?!FRAUD_RULES.slice(0,3).some(r=>r.test(raw)):c.re.test(full);if(ok)earned+=w;});return Math.round(earned/total*100);}
function batchProcess(o){const turns=parseConvo(o.convo);const raw=turns.map(t=>t.text).join(' ');const score=evalConvoText(raw);const match=findAgent(o.agent,o.agentId);const rec={id:'INT-'+Date.now()+'-'+Math.floor(Math.random()*999),date:new Date().toISOString(),mode:'Batch Upload',agent:match?(match.first+' '+match.last):(o.agent||'Unknown'),agentId:o.agentId||(match?match.emp:''),site:match?match.site:'',bu:match?match.bu:'',section:match?match.section:'',sub:match?match.sub:'',matched:!!match,file:o.file||'',lang:o.lang||'Auto',durationSec:0,turns:turns.length,sentiment:{pos:0,neu:turns.length,neg:0,dom:'Neutral'},fraudScore:0,gapPct:score,resolved:score>=70,transcript:turns};const ia=loadInteractions();ia.unshift(rec);saveInteractionsArr(ia);const ba=loadBatch();ba.unshift(rec);saveBatch(ba);awardPoints(rec.agent,{quality:score,training:0,tag:'Batch upload',agentId:rec.agentId});return rec;}
function batchAddSingle(){const convo=document.getElementById('bConvo').value.trim();const msg=document.getElementById('bMsg');if(!convo){msg.style.color='var(--red)';msg.textContent='⚠️ Conversation required.';return;}const rec=batchProcess({file:document.getElementById('bFile').value.trim(),agent:document.getElementById('bAgent').value.trim(),agentId:document.getElementById('bAgentId').value.trim(),convo,lang:document.getElementById('bLang').value});batchClearForm();msg.style.color='var(--green)';msg.textContent='✅ Score '+rec.gapPct+'%'+(rec.matched?' · '+rec.site+'/'+rec.bu:' · unmatched')+' · saved & posted.';renderBatch();renderLibrary();setTimeout(()=>msg.textContent='',4500);}
function batchClearForm(){['bFile','bAgent','bAgentId','bConvo','bStart','bEnd'].forEach(id=>document.getElementById(id).value='');document.getElementById('bMatch').className='';document.getElementById('bMatch').textContent='';}
function batchUploadCSV(ev){const f=ev.target.files[0];if(!f)return;const c=document.getElementById('bCsvMsg');const r=new FileReader();r.onload=()=>{const rows=parseCSV(r.result);if(rows.length<2){c.className='conn err';c.textContent='Invalid CSV.';return;}const hdr=rows[0].map(h=>h.trim().toLowerCase());const idx=n=>hdr.findIndex(h=>h.includes(n));const iF=idx('file'),iN=idx('agent name'),iI=idx('agent id'),iC=idx('conversation');let n=0,mt=0;for(let i=1;i<rows.length;i++){const row=rows[i];const conv=row[iC>=0?iC:3];if(!conv)continue;const rec=batchProcess({file:row[iF]||('row'+i),agent:row[iN]||'Unknown',agentId:row[iI]||'',convo:conv});if(rec.matched)mt++;n++;}c.className='conn ok';c.textContent='✅ Processed '+n+' ('+mt+' matched).';renderBatch();renderLibrary();logAudit('Batch CSV uploaded',n+' rows','data');};r.readAsText(f);ev.target.value='';}
function renderBatch(){const arr=loadBatch();const tbl=document.getElementById('batchTable');if(!tbl)return;while(tbl.rows.length>1)tbl.deleteRow(1);document.getElementById('batchCount').textContent=arr.length;document.getElementById('batchEmpty').style.display=arr.length?'none':'block';arr.forEach(r=>{const tr=tbl.insertRow(-1);tr.innerHTML='<td>'+(r.file||'—')+'</td><td>'+r.agent+'</td><td>'+(r.agentId||'—')+'</td><td>'+(r.matched?r.site+'/'+r.bu:'<span style="color:var(--muted)">unmatched</span>')+'</td><td>'+r.turns+'</td><td><b style="color:'+(r.gapPct>=85?'var(--green)':r.gapPct>=70?'var(--amber)':'var(--red)')+'">'+r.gapPct+'%</b></td><td><span class="tag '+(r.resolved?'':'y')+'">'+(r.resolved?'Resolved':'Follow-up')+'</span></td>';});}
function exportBatch(){let out="File,Agent,Agent ID,Site,BU,Turns,Score,Outcome\n";loadBatch().forEach(r=>out+=[r.file,r.agent,r.agentId,r.site,r.bu,r.turns,r.gapPct+'%',r.resolved?'Resolved':'Follow-up'].map(csvEsc).join(',')+'\n');dl(out,"FANTASTIC_batch.csv","text/csv");}
/* ===== QA FORM RESULTS — CSV EXPORT (v3.2) ===== */
function qaFormFor(r){if(r.qaForm&&(r.qaForm.well||r.qaForm.wrong||r.qaForm.improve))return {well:r.qaForm.well||[],wrong:r.qaForm.wrong||[],improve:r.qaForm.improve||[]};try{const g=autoGap(r);const well=(g.checks||[]).filter(c=>c.ok).map(c=>c.label);const wrong=(g.gaps||[]).map(c=>c.label);const improve=(g.gaps||[]).map(c=>'Improve: '+c.label);return {well,wrong,improve};}catch(e){return {well:[],wrong:[],improve:[]};}}
function exportQAResults(recs,fname){const arr=(recs&&recs.length)?recs:loadInteractions().filter(r=>r.gapPct!=null||r.manualRating||r.qaForm);if(!arr.length){alert('No QA form results to export yet. Complete a call, batch upload, or evaluation first.');return;}const cols=['Date','Interaction ID','Agent','Employee #','Site','BU','Section','Sub-section','Mode','Scenario','Language','Turns','Duration (s)','Auto QA Score','Manual Rating (stars)','Manual Score','Sentiment','Positive','Neutral','Negative','Agent Mood','Fraud Score','Resolved','Interruptions','What Went Well','What Went Wrong','Areas for Improvement','Evaluator Note','Rated By','AI Summary'];let out=cols.map(csvEsc).join(',')+'\n';arr.forEach(r=>{const qf=qaFormFor(r);const s=r.sentiment||{};const row=[new Date(r.date).toLocaleString(),r.id,r.agent||'',r.agentId||'',r.site||'',r.bu||'',r.section||'',r.sub||'',r.mode||'',r.scenario||'',r.lang||'',r.turns!=null?r.turns:'',r.durationSec!=null?r.durationSec:'',r.gapPct!=null?r.gapPct:'',r.manualRating!=null?r.manualRating:'',r.manualScore!=null?r.manualScore:'',(r.qaForm&&r.qaForm.dom)||s.dom||'',s.pos!=null?s.pos:'',s.neu!=null?s.neu:'',s.neg!=null?s.neg:'',r.mood!=null?r.mood:(r.qaForm&&r.qaForm.mood!=null?r.qaForm.mood:''),r.fraudScore!=null?r.fraudScore:'',r.resolved?'Resolved':'Follow-up',r.interruptions!=null?r.interruptions:'',(qf.well||[]).join(' | '),(qf.wrong||[]).join(' | '),(qf.improve||[]).join(' | '),r.evalNote||'',r.ratedBy||'',(r.summary||'').replace(/\s+/g,' ').trim()];out+=row.map(csvEsc).join(',')+'\n';});const name=fname||('FANTASTIC_QA_form_results_'+new Date().toISOString().slice(0,10)+'.csv');dl(out,name,'text/csv');try{logAudit('Exported QA form results',arr.length+' records','export');}catch(e){}}
window.exportQAResults=exportQAResults;
function exportEvalQA(){const f=((document.getElementById('evSearch')||{}).value||'').toLowerCase();let ia=loadInteractions();if(f)ia=ia.filter(r=>((r.agent||'')+(r.mode||'')+(r.site||'')).toLowerCase().includes(f));exportQAResults(ia,'FANTASTIC_QA_form_results_'+new Date().toISOString().slice(0,10)+'.csv');}
window.exportEvalQA=exportEvalQA;
function exportLiveQA(){const r=loadInteractions().find(x=>x.id===window._lastLiveId);if(!r){alert('Complete a call first to generate a QA form result.');return;}exportQAResults([r],'FANTASTIC_QA_'+r.id+'.csv');}
window.exportLiveQA=exportLiveQA;
function downloadCSVTemplate(){dl("File Name,Agent Name,Agent ID,Conversation,Interaction Start Time,Interaction End Time\ncall_001.wav,Juan Dela Cruz,EMP-1001,\"Agent: Thank you for calling. | Customer: My bill is wrong. | Agent: Let me verify and file a dispute.\",2026-07-24 09:00,2026-07-24 09:05\n","FANTASTIC_batch_template.csv","text/csv");}
function teamRollup(){const field=document.getElementById('teamGroup').value;const ia=loadInteractions();const g={};ia.forEach(r=>{let key=r[field];if(!key){const ag=findAgent(r.agent,r.agentId);if(ag)key=ag[field];}if(!key)return;if(!g[key])g[key]={key,n:0,sum:0,resolved:0,agents:{}};const x=g[key];x.n++;x.sum+=(r.gapPct||0);if(r.resolved)x.resolved++;const an=r.agent||'Unknown';if(!x.agents[an])x.agents[an]={name:an,n:0,sum:0};x.agents[an].n++;x.agents[an].sum+=(r.gapPct||0);});return Object.values(g).map(x=>({...x,avg:x.n?Math.round(x.sum/x.n):0,resRate:x.n?Math.round(x.resolved/x.n*100):0,leader:Object.values(x.agents).map(a=>({...a,avg:Math.round(a.sum/a.n)})).sort((a,b)=>b.avg-a.avg)[0]})).sort((a,b)=>b.avg-a.avg);}
function heatColor(v){return v>=85?'#16a34a':v>=70?'#f59e0b':'#dc2626';}
function renderTeam(){const field=document.getElementById('teamGroup').value;const labels={site:'Sites',bu:'BUs',section:'Sections',sub:'Sub-sections'};const rows=teamRollup();document.getElementById('tmGroupsLab').textContent=labels[field];document.getElementById('tmGroups').textContent=rows.length;const tot=rows.reduce((a,r)=>a+r.n,0);document.getElementById('tmInteractions').textContent=tot;document.getElementById('tmAvg').textContent=tot?Math.round(rows.reduce((a,r)=>a+r.sum,0)/tot)+'%':'—';document.getElementById('tmTop').textContent=rows.length?rows[0].key:'—';document.getElementById('teamEmpty').style.display=rows.length?'none':'block';const L=document.getElementById('teamLeaders');if(!rows.length){L.innerHTML='<div class="note">No matched interactions yet.</div>';document.getElementById('teamBars').innerHTML='';document.getElementById('teamVol').innerHTML='';document.getElementById('teamDetail').innerHTML='';return;}L.innerHTML='<div class="grid g3">'+rows.map(r=>r.leader?'<div class="team-card"><div class="th"><b>'+r.key+'</b><span class="lb-av">'+r.leader.name.substring(0,2).toUpperCase()+'</span></div><div style="margin-top:6px"><b>🏅 '+r.leader.name+'</b> <span class="team-score" style="font-size:16px;color:'+heatColor(r.leader.avg)+'">'+r.leader.avg+'%</span><div class="note">'+r.leader.n+' interactions · top in '+r.key+'</div></div></div>':'').join('')+'</div>';const maxA=Math.max(...rows.map(r=>r.avg),1);document.getElementById('teamBars').innerHTML=rows.map(r=>'<div class="hbar-row"><span class="name">'+r.key+'</span><div class="track"><span style="width:'+Math.max(12,r.avg/maxA*100)+'%;background:'+heatColor(r.avg)+'">'+r.avg+'%</span></div></div>').join('');const maxN=Math.max(...rows.map(r=>r.n),1);document.getElementById('teamVol').innerHTML=rows.slice().sort((a,b)=>b.n-a.n).map(r=>'<div class="hbar-row"><span class="name">'+r.key+'</span><div class="track"><span style="width:'+Math.max(12,r.n/maxN*100)+'%">'+r.n+'</span></div></div>').join('');document.getElementById('teamDetail').innerHTML=rows.map(r=>'<div class="team-card"><div class="th"><b>'+r.key+'</b><span class="team-score" style="color:'+heatColor(r.avg)+'">'+r.avg+'%</span></div><div class="team-meta"><span>💬 '+r.n+'</span><span>✅ '+r.resRate+'% resolved</span><span>🏅 '+(r.leader?r.leader.name:'—')+'</span></div></div>').join('');}
function exportTeam(){const rows=teamRollup();let out="Group,Interactions,AvgScore,ResolvedRate,Leader,LeaderScore\n";rows.forEach(r=>out+=[r.key,r.n,r.avg+'%',r.resRate+'%',r.leader?r.leader.name:'',r.leader?r.leader.avg+'%':''].map(csvEsc).join(',')+'\n');dl(out,"FANTASTIC_team.csv","text/csv");logAudit('Exported team dashboard','','export');}
function loadLB(){return read('ft_leaderboard',{});}
function saveLB(o){store('ft_leaderboard',o);}
function levelFor(p){return Math.max(1,Math.floor(p/250)+1);}
function rankName(l){return ['Rookie','Bronze','Silver','Gold','Platinum','Diamond','Master','Grandmaster'][Math.min(l-1,7)]||'Legend';}
function awardPoints(name,{quality=0,training=0,tag='',agentId=''}){if(!name)name='Agent';const lb=loadLB();const ag=findAgent(name,agentId);const key=agentId||(ag?ag.emp:name);const p=lb[key]||{name,agentId,points:0,sessions:0,trainingCount:0,qualitySum:0,qualityN:0,bestQuality:0,bestTraining:0,hist:[]};p.name=ag?(ag.first+' '+ag.last):name;if(ag){p.site=ag.site;p.bu=ag.bu;p.section=ag.section;p.agentId=ag.emp;}else if(agentId)p.agentId=agentId;const pts=Math.round(quality*2+training*1.5);p.points+=pts;p.sessions++;if(training>0){p.trainingCount++;p.bestTraining=Math.max(p.bestTraining,training);}if(quality>0){p.qualitySum+=quality;p.qualityN++;p.bestQuality=Math.max(p.bestQuality,quality);}p.hist=(p.hist||[]).concat(quality||training).slice(-10);lb[key]=p;saveLB(lb);renderLeaderboard();populateLbSites();}
function populateLbSites(){const lb=loadLB();const sites=[...new Set(Object.values(lb).map(p=>p.site).filter(Boolean))];const sel=document.getElementById('lbSite');if(!sel)return;const cur=sel.value;sel.innerHTML='<option value="all">All sites</option>'+sites.map(s=>'<option>'+s+'</option>').join('');if(cur)sel.value=cur;}
function renderLeaderboard(){const lb=loadLB();const fEl=document.getElementById('lbFilter');if(!fEl)return;const filter=fEl.value,site=document.getElementById('lbSite').value;let arr=Object.values(lb).map(p=>({...p,avgQuality:p.qualityN?Math.round(p.qualitySum/p.qualityN):0}));if(site!=='all')arr=arr.filter(p=>p.site===site);if(filter==='quality')arr=arr.filter(p=>p.qualityN>0).sort((a,b)=>b.bestQuality-a.bestQuality);else if(filter==='training')arr=arr.filter(p=>p.trainingCount>0).sort((a,b)=>b.bestTraining-a.bestTraining);else arr.sort((a,b)=>b.points-a.points);document.getElementById('lbEmpty').style.display=arr.length?'none':'block';const pod=document.getElementById('podium');const top3=arr.slice(0,3),order=[1,0,2],cls=['p2','p1','p3'],medal=['🥈','🥇','🥉'];pod.innerHTML=order.map((oi,i)=>{const p=top3[oi];if(!p)return'';return '<div class="pod '+cls[i]+'"><div class="medal">'+medal[i]+'</div><div class="nm">'+p.name+'</div><div class="pts">'+p.points+'</div><div style="font-size:10px">'+rankName(levelFor(p.points))+'</div></div>';}).join('');document.getElementById('lbList').innerHTML=arr.map((p,i)=>{const lvl=levelFor(p.points);const metric=filter==='quality'?p.bestQuality+' best QA':filter==='training'?p.bestTraining+'% sim':p.points+' pts';return '<div class="lb-row"><div class="lb-rank">'+(i+1)+'</div><div class="lb-av">'+p.name.substring(0,2).toUpperCase()+'</div><div class="lb-info"><b>'+p.name+'</b><span class="lvl">Lv.'+lvl+' '+rankName(lvl)+'</span><div class="sub">'+((p.site?p.site+' · ':'')+(p.bu?p.bu+' · ':'')+p.sessions+' sessions · avg QA '+p.avgQuality)+'</div></div><div class="lb-pts">'+metric+'</div></div>';}).join('');}
function exportLeaderboard(){const lb=loadLB();let out="Agent,Agent ID,Site,BU,Points,Level,Sessions,AvgQuality,BestQuality\n";Object.values(lb).forEach(p=>out+=[p.name,p.agentId||'',p.site||'',p.bu||'',p.points,levelFor(p.points),p.sessions,p.qualityN?Math.round(p.qualitySum/p.qualityN):0,p.bestQuality].map(csvEsc).join(',')+'\n');dl(out,"FANTASTIC_leaderboard.csv","text/csv");logAudit('Exported leaderboard','','export');}
function loadInteractions(){return read('ft_interactions',[]);}
function saveInteractionsArr(a){store('ft_interactions',a);}
function saveInteraction(){const arr=loadInteractions();const dom=sNeg>=sPos&&sNeg>=sNeu?'Negative':sPos>=sNeu?'Positive':'Neutral';const kbHits=convo.filter(c=>c.kb).length;const gapPct=(window._gapData&&window._gapData.pct)||null;const nm=document.getElementById('agInput').value;const ag=findAgent(nm,'');const rec={id:'INT-'+Date.now(),date:new Date().toISOString(),mode:roleMode==='customer'?'Training (AI customer)':'Live (AI agent)',scenario:roleMode==='customer'&&scen?scen.label:'',agent:nm,agentId:ag?ag.emp:'',site:ag?ag.site:'',bu:ag?ag.bu:'',section:ag?ag.section:'',sub:ag?ag.sub:'',lang:langLabel(curLang),mood:Math.round(moodVal),durationSec:Math.floor((Date.now()-startTime)/1000),turns:custTurns,sentiment:{pos:sPos,neu:sNeu,neg:sNeg,dom},fraudScore,gapPct,resolved:(roleMode==='customer')?scenResolved:(kbHits>0&&dom!=='Negative'),summary:window._aiSummary||'',transcript:convo.map(c=>({role:c.role||(c.who==='ai'?'agent':'customer'),who:c.who,text:c.text,empathized:c.empathized}))};arr.unshift(rec);saveInteractionsArr(arr);window._lastLiveId=rec.id;renderLibrary();}
function replayHTML(r){return (r.transcript||[]).map(m=>'<div class="msg '+(m.who||'cust')+'"><div class="who">'+(m.role==='agent'?'🎧 Agent':'🧑 Customer')+'</div><span class="txt">'+esc(m.text)+'</span></div>').join('')+(r.summary?'<div class="ai-guide-box" style="margin-top:10px"><b>AI Summary:</b><br>'+esc(r.summary).replace(/\n/g,'<br>')+'</div>':'');}
function renderLibrary(filter){filter=filter||'';const arr=loadInteractions();const list=document.getElementById('libList');if(!list)return;const avgGap=arr.filter(r=>r.gapPct!=null);const gapAvg=avgGap.length?Math.round(avgGap.reduce((a,r)=>a+r.gapPct,0)/avgGap.length):'—';const st=document.getElementById('libStats');if(st)st.innerHTML='<div class="fchip"><b>'+arr.length+'</b> saved</div><div class="fchip"><b>'+arr.filter(r=>r.resolved).length+'</b> resolved</div><div class="fchip"><b>'+arr.filter(r=>r.manualRating).length+'</b> rated</div><div class="fchip">Avg gap <b>'+gapAvg+(gapAvg==='—'?'':'%')+'</b></div>';const f=filter.toLowerCase();const shown=arr.filter(r=>(r.mode+(r.agent||'')+(r.site||'')+(r.bu||'')+(r.lang||'')).toLowerCase().includes(f));document.getElementById('libEmpty').style.display=arr.length?'none':'block';list.innerHTML=shown.map(r=>{const d=new Date(r.date);const gap=r.gapPct!=null?'<span>🧩 '+r.gapPct+'%</span>':'';const rate=r.manualRating?'<span>⭐ '+r.manualRating+'/5</span>':'';const lang=r.lang?'<span>🌐 '+r.lang+'</span>':'';const mood=(r.mood!=null)?'<span>🙂 '+r.mood+'</span>':'';const org=(r.site||r.bu)?'<span>🏢 '+[r.site,r.bu].filter(Boolean).join('/')+'</span>':'';const who=r.agent?'<span>👤 '+esc(r.agent)+'</span>':'';return '<div class="lib-card"><div class="lib-head"><div><b>'+d.toLocaleString()+'</b> <span class="kb-custom">'+r.mode+'</span><div class="lib-meta">'+who+org+lang+mood+'<span>💬 '+r.turns+'</span>'+gap+rate+'<span class="tag '+(r.resolved?'':'y')+'" style="margin:0">'+(r.resolved?'Resolved':'Follow-up')+'</span></div></div><div class="lib-actions"><button onclick="toggleReplay(\''+r.id+'\')"> View</button><button onclick="exportInteraction(\''+r.id+'\')">Download</button><button class="del" onclick="deleteInteraction(\''+r.id+'\')">Delete</button></div></div><div class="replay" id="rp_'+r.id+'">'+replayHTML(r)+'</div></div>';}).join('');}
function toggleReplay(id){const el=document.getElementById('rp_'+id);if(!el)return;el.style.display=el.style.display==='block'?'none':'block';}
window.toggleReplay=toggleReplay;
function exportInteraction(id){const r=loadInteractions().find(x=>x.id===id);if(!r)return;let out="FANTASTIC — Interaction\n"+new Date(r.date).toLocaleString()+"\nAgent: "+(r.agent||'')+"\nLanguage: "+(r.lang||'')+"\nMood: "+(r.mood??'—')+"\nScore: "+(r.gapPct??'—')+(r.manualRating?"\nRating: "+r.manualRating+"/5":'')+"\n\n";r.transcript.forEach(m=>out+=(m.role==='agent'?'Agent':'Customer')+": "+m.text+"\n");if(r.summary)out+="\n=== AI SUMMARY ===\n"+r.summary+"\n";dl(out,"FANTASTIC_"+r.id+".txt","text/plain");}
function deleteInteraction(id){if(!confirm('Delete?'))return;saveInteractionsArr(loadInteractions().filter(x=>x.id!==id));renderLibrary(document.getElementById('libSearch').value);}
function downloadAllInteractions(){const arr=loadInteractions();if(!arr.length){alert('Empty.');return;}dl(JSON.stringify(arr,null,2),"FANTASTIC_interactions.json","application/json");}
function clearAllInteractions(){if(!confirm('Clear ALL?'))return;localStorage.removeItem('ft_interactions');renderLibrary();logAudit('Cleared interactions','','data');}
const libS=document.getElementById('libSearch');if(libS)libS.oninput=e=>renderLibrary(e.target.value);
function buildLiveQA(){const well=[],wrong=[],imp=[];const dom=sNeg>=sPos&&sNeg>=sNeu?'Negative':sPos>=sNeu?'Positive':'Neutral';const kbHits=convo.filter(c=>c.kb).length;const hasGreet=convo.some(c=>c.role==='agent'&&/(hello|hi|welcome|thank you for calling|kumusta|magandang|maayong|naimbag|maupay)/i.test(c.text||''));const hasEmp=convo.some(c=>c.empathized)||convo.some(c=>c.role==='agent'&&/(sorry|apolog|pasensya|pasaylo|nasabtan)/i.test(c.text||''));const endDetected=convo.some(c=>c.end);const crit=fraudFlags.some(f=>f.sev==='critical');if(hasGreet)well.push('Branded, warm opening delivered.');else{wrong.push('No clear branded greeting.');imp.push('Open with a branded greeting in the first 5 seconds.');}well.push('Replied in the caller\u2019s language ('+langLabel(curLang)+').');if(hasEmp)well.push('Apology + empathy expressed.');else if(dom==='Negative'){wrong.push('Missing apology/empathy for an upset customer.');imp.push('Apologize sincerely, then empathize before the solution.');}if(kbHits>0)well.push('Answers anchored to the Knowledge Base ('+kbHits+').');else{wrong.push('No KB-backed answer detected.');imp.push('Anchor responses to KB articles.');}if(dom!=='Negative')well.push('Overall sentiment stayed '+dom.toLowerCase()+'.');else{wrong.push('Customer sentiment trended negative.');imp.push('Acknowledge frustration earlier.');}if(camOn)well.push('Agent mood tracked ('+moodLabelFor(moodVal)+', '+Math.round(moodVal)+'/100).');if(endDetected)well.push('End-of-call intent detected & acknowledged.');if(crit){wrong.push('⚠️ Critical compliance flag.');imp.push('Never collect card/OTP over voice.');}else well.push('No critical compliance issues.');if(!imp.length)imp.push('Maintain this standard — great handling! 🌟');const fill=(id,a)=>{const el=document.getElementById(id);el.innerHTML=a.map(x=>'<li>'+x+'</li>').join('');};fill('qaWell',well);fill('qaWrong',wrong);fill('qaImprove',imp);const pct=(window._gapData&&window._gapData.pct)||0;try{const _ia=loadInteractions();const _ix=_ia.findIndex(x=>x.id===window._lastLiveId);if(_ix>=0){_ia[_ix].qaForm={well,wrong,improve:imp,dom,mood:Math.round(moodVal),endDetected,crit};saveInteractionsArr(_ia);}}catch(e){}document.getElementById('liveQAScore').innerHTML='Auto QA: <b style="color:'+(pct>=85?'var(--green)':pct>=70?'var(--amber)':'var(--red)')+'">'+pct+'/100</b> · Sentiment: '+dom+' · Mood: '+moodLabelFor(moodVal)+(endDetected?' · 📞 end detected':'');document.getElementById('liveQAempty').classList.add('hidden');document.getElementById('liveQAbody').classList.remove('hidden');window._liveStars=0;document.querySelectorAll('#liveStars .st').forEach(s=>s.classList.remove('on'));const rm=document.getElementById('liveRateMsg');rm.className='';rm.textContent='';}
function submitLiveRating(){const stars=window._liveStars||0;const rm=document.getElementById('liveRateMsg');if(!stars){rm.className='conn err';rm.textContent='⚠️ Please tap the stars to rate first.';return;}const note=document.getElementById('liveRateNote').value.trim();const arr=loadInteractions();const idx=arr.findIndex(x=>x.id===window._lastLiveId);const scaled=stars*20;if(idx>=0){arr[idx].manualRating=stars;arr[idx].manualScore=scaled;arr[idx].evalNote=note;arr[idx].ratedBy=currentUser?currentUser.user:'';saveInteractionsArr(arr);}awardPoints(document.getElementById('agInput').value||'FANTASTIC AI',{quality:scaled,training:0,tag:'Live QA rating'});logAudit('Live call rated',stars+'★ ('+scaled+'/100)','data');rm.className='conn ok';rm.textContent='✅ Rating submitted: '+stars+'★ ('+scaled+'/100). Saved & posted.';renderLibrary();}
function myInteractions(){const ia=loadInteractions();const emp=(loadUsers().find(u=>u.user===currentUser.user)||{}).emp;const nm=currentUser.name.toLowerCase();return ia.filter(r=>(emp&&r.agentId===emp)||(r.agent||'').toLowerCase()===nm);}
function coachForMe(){const emp=currentUser.user;const nm=(currentUser.name||'').toLowerCase();return loadCoach().filter(x=>x.toUser===emp||(x.toName||'').toLowerCase()===nm);}
function renderAgentDash(){const mine=myInteractions();const sc=mine.filter(r=>r.gapPct!=null);const avg=sc.length?Math.round(sc.reduce((a,r)=>a+r.gapPct,0)/sc.length):'—';const lb=loadLB();const emp=(loadUsers().find(u=>u.user===currentUser.user)||{}).emp;const me=lb[emp]||Object.values(lb).find(p=>p.name.toLowerCase()===currentUser.name.toLowerCase())||{points:0,bestQuality:0,sessions:0,hist:[]};document.getElementById('adKpis').innerHTML=[['My Interactions',mine.length],['My Avg Quality',avg+(avg==='—'?'':'%')],['My Points',me.points||0],['My Rank',rankName(levelFor(me.points||0))]].map(k=>'<div class="stat"><div class="n">'+k[1]+'</div><div class="l">'+k[0]+'</div></div>').join('');const hist=(me.hist||[]).length?me.hist:sc.slice(0,7).reverse().map(r=>r.gapPct||0);sparkline('adSpark',hist.length?hist:[0],100);document.getElementById('adTrend').textContent=hist.length?('Last '+hist.length+' scores'):'Complete a call to see your trend.';const ACH=[['🎉','First Call',mine.length>=1],['⭐','Quality Star',(me.bestQuality||0)>=90],['🔥','On Fire',(me.sessions||0)>=5],['👑','Legend',(me.points||0)>=1000]];document.getElementById('adAch').innerHTML=ACH.map(a=>'<div class="b '+(a[2]?'earned':'locked')+'"><div class="em">'+a[0]+'</div><div class="t">'+a[1]+'</div></div>').join('');const cs=coachForMe();document.getElementById('myCoachList').innerHTML=cs.length?cs.map(x=>'<div class="lib-card"><div class="lib-head"><div><b>'+esc(x.fromName||x.from)+'</b>'+(x.topic?' <span class="tag">'+esc(x.topic)+'</span>':'')+'<div class="lib-meta"><span>'+new Date(x.ts).toLocaleString()+'</span></div><div class="script-card" style="margin-top:6px">'+mdToHtml(x.body)+'</div></div><div class="lib-actions">'+(x.ack?'<span class="tag" style="background:#dcfce7;color:#166534">✓ acknowledged</span>':'<button onclick="ackCoach(\''+x.id+'\')">✅ Acknowledge</button>')+' <button onclick="dmOpen(\''+esc(x.from)+'\')">💬 Reply</button></div></div></div>').join(''):'<div class="note">No coaching notes yet. Your supervisor\u2019s notes will appear here.</div>';document.getElementById('adList').innerHTML=mine.length?mine.slice(0,10).map(r=>'<div class="lib-card"><div class="lib-head"><div><b>'+new Date(r.date).toLocaleString()+'</b><div class="lib-meta"><span>'+r.mode+'</span><span>🧩 '+(r.gapPct??'—')+'%</span>'+(r.manualRating?'<span>⭐ '+r.manualRating+'/5</span>':'')+'</div></div><div class="lib-actions"><button onclick="toggleReplay(\''+r.id+'\')">👁 View</button></div></div><div class="replay" id="rp_'+r.id+'">'+replayHTML(r)+'</div></div>').join(''):'<div class="note">No interactions yet.</div>';}
function ackCoach(id){const c=loadCoach();const x=c.find(v=>v.id===id);if(x){x.ack=true;saveCoach(c);renderAgentDash();notify('supervisor',x.from,'✅ '+currentUser.name+' acknowledged your coaching note.','coach');logAudit('Coaching acknowledged','from '+(x.fromName||x.from),'data');}}
window.ackCoach=ackCoach;
function autoGap(rec){const tx=(rec.transcript||[]);const ag=tx.filter(m=>m.role==='agent').map(m=>(m.text||'').toLowerCase()).join(' ');const cu=tx.filter(m=>m.role!=='agent').map(m=>(m.text||'').toLowerCase()).join(' ');const checks=[{id:'greet',label:'Branded greeting',topic:'closing',ok:/(hello|hi|welcome|thank you for calling|kumusta|magandang|maayong|naimbag|maupay)/.test(ag)},{id:'empathy',label:'Empathy & apology',topic:'empathy',ok:/(sorry|apolog|understand|pasensya|pasaylo|nasabtan|dispensar|maawatak)/.test(ag)||tx.some(m=>m.empathized)},{id:'verify',label:'Identity verification',topic:'verify',ok:/(verify|otp|account number|i-verify)/.test(ag)||!/(account|refund|billing|charge|cancel|password)/.test(cu)},{id:'resolve',label:'Resolution provided',topic:'billing',ok:/(i'll|let me|i can|process|file|resolve|fix|refund|credit|gagawin|ayusin|tabang|bulig)/.test(ag)},{id:'compliance',label:'PCI/compliance',topic:'compliance',ok:!/(cvv|full card|otp is|password is)/.test(ag+cu)},{id:'close',label:'Proper closing',topic:'closing',ok:/(anything else|glad to help|thank you for calling|may iba pa|paalam|salamat po|babay|agyaman)/.test(ag)}];const gaps=checks.filter(c=>!c.ok);const pct=Math.round((checks.length-gaps.length)/checks.length*100);return {pct,gaps,checks,topTopic:gaps[0]?gaps[0].topic:null};}
function evalActionsHTML(rec){const topics=loadTopics();const sups=loadUsers().filter(u=>u.role==='supervisor'&&u.status==='active');return '<div class="script-card" style="margin-top:10px"><div class="row" style="justify-content:space-between"><b>🧪 QA action</b><button class="btn ghost" style="padding:4px 10px;font-size:11px" onclick="evAutoGap(\''+rec.id+'\')">⚡ Auto gap analysis</button></div><div id="gap_'+rec.id+'" class="note" style="margin-top:6px"></div><div class="tgrid" style="margin-top:8px"><div><label class="fld">Recommend enroll to topic</label><select class="inp" id="etopic_'+rec.id+'">'+topics.map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join('')+'</select></div><div><label class="fld">Send to supervisor</label><select class="inp" id="esup_'+rec.id+'"><option value="">(any supervisor)</option>'+sups.map(u=>'<option value="'+u.user+'">'+esc(u.name)+'</option>').join('')+'</select></div></div><label class="fld" style="margin-top:6px">Evaluation notes (Markdown)</label><textarea id="enote_'+rec.id+'" placeholder="## Coaching&#10;- **Empathy:** apologize sooner&#10;- Enroll to *De-escalation*"></textarea><div class="row" style="margin-top:8px"><button class="btn" onclick="evSend(\''+rec.id+'\')">📤 Send eval to Supervisor</button><button class="btn yellow" onclick="evRecommend(\''+rec.id+'\')">🎓 Recommend enrollment</button><span class="note" id="emsg_'+rec.id+'" style="margin:0"></span></div></div>';}
function renderEval(){const f=(document.getElementById('evSearch')?.value||'').toLowerCase();const ia=loadInteractions();const scored=ia.filter(r=>r.gapPct!=null);const avg=scored.length?Math.round(scored.reduce((a,r)=>a+r.gapPct,0)/scored.length):'—';document.getElementById('evKpis').innerHTML=[['To Review',ia.length],['Avg Quality',avg+(avg==='—'?'':'%')],['Below 70%',scored.filter(r=>r.gapPct<70).length],['Rated',ia.filter(r=>r.manualRating).length]].map(k=>'<div class="stat"><div class="n">'+k[1]+'</div><div class="l">'+k[0]+'</div></div>').join('');const bands={'85-100':0,'70-84':0,'50-69':0,'<50':0};scored.forEach(r=>{const s=r.gapPct;if(s>=85)bands['85-100']++;else if(s>=70)bands['70-84']++;else if(s>=50)bands['50-69']++;else bands['<50']++;});hbars('evDist',Object.entries(bands).map(([n,v])=>({n,v})));const low=scored.slice().sort((a,b)=>a.gapPct-b.gapPct).slice(0,5);document.getElementById('evLow').innerHTML=low.length?low.map(r=>'<div class="hbar-row"><span class="name">'+esc(r.agent||'Unknown')+'</span><div class="track"><span style="width:'+Math.max(12,r.gapPct)+'%;background:'+heatColor(r.gapPct)+'">'+r.gapPct+'%</span></div></div>').join(''):'<div class="note">No scored interactions.</div>';const shown=ia.filter(r=>((r.agent||'')+(r.mode||'')+(r.site||'')).toLowerCase().includes(f));document.getElementById('evList').innerHTML=shown.length?shown.slice(0,20).map(r=>'<div class="lib-card"><div class="lib-head"><div><b>'+esc(r.agent||'Unknown')+'</b> <span class="kb-custom">'+r.mode+'</span><div class="lib-meta"><span>'+new Date(r.date).toLocaleDateString()+'</span><span>🧩 '+(r.gapPct??'—')+'%</span>'+(r.manualRating?'<span>⭐ '+r.manualRating+'/5</span>':'')+(r.lang?'<span>🌐 '+r.lang+'</span>':'')+'</div></div><div class="lib-actions"><button onclick="toggleReplay(\''+r.id+'\')">👁 Review</button></div></div><div class="replay" id="rp_'+r.id+'">'+replayHTML(r)+'</div>'+evalActionsHTML(r)+'</div>').join(''):'<div class="note">No interactions to review.</div>';}
function evAutoGap(id){const rec=loadInteractions().find(x=>x.id===id);if(!rec)return;const g=autoGap(rec);const box=document.getElementById('gap_'+id);box.innerHTML='Auto QA: <b style="color:'+(g.pct>=85?'var(--green)':g.pct>=70?'var(--amber)':'var(--red)')+'">'+g.pct+'/100</b> · Gaps: '+(g.gaps.length?g.gaps.map(x=>'<span class="tag r">'+x.label+'</span>').join(''):'<span class="tag">none 🎉</span>')+(g.topTopic?(' · Suggested: <b>'+(topicById(g.topTopic)||{}).name+'</b>'):'');if(g.topTopic){const sel=document.getElementById('etopic_'+id);if(sel)sel.value=g.topTopic;}window['_gap_'+id]=g;logAudit('Auto gap analysis',rec.agent+' · '+g.pct+'%','data');}
window.evAutoGap=evAutoGap;
function evSend(id){const rec=loadInteractions().find(x=>x.id===id);if(!rec)return;const g=window['_gap_'+id]||autoGap(rec);const topicId=(document.getElementById('etopic_'+id)||{}).value;const sup=(document.getElementById('esup_'+id)||{}).value;const note=(document.getElementById('enote_'+id)||{}).value||'';const evs=loadEvals();evs.unshift({id:'EV-'+Date.now(),interactionId:rec.id,agent:rec.agent,agentId:rec.agentId||'',site:rec.site||'',score:g.pct,gaps:g.gaps.map(x=>x.label),topicId,note,from:currentUser.user,to:sup||'',status:'sent',ts:new Date().toISOString()});saveEvals(evs);notify('supervisor',sup,'📥 New QA eval for '+rec.agent+' ('+g.pct+'/100) — please review.','eval');document.getElementById('emsg_'+id).style.color='var(--green)';document.getElementById('emsg_'+id).textContent='✅ Sent to supervisor.';logAudit('Evaluation sent','agent '+rec.agent+' → supervisor '+(sup||'any'),'data');refreshBell();}
window.evSend=evSend;
function evRecommend(id){const rec=loadInteractions().find(x=>x.id===id);if(!rec)return;const topicId=(document.getElementById('etopic_'+id)||{}).value;const note=(document.getElementById('enote_'+id)||{}).value||'';const en=loadEnroll();en.unshift({id:'EN-'+Date.now(),agent:rec.agent,agentId:rec.agentId||'',site:rec.site||'',topicId,note,by:currentUser.user,status:'pending',ts:new Date().toISOString(),interactionId:rec.id});saveEnroll(en);notify('trainer','','🎓 New enrollment: '+rec.agent+' → '+((topicById(topicId)||{}).name||topicId),'enroll');document.getElementById('emsg_'+id).style.color='var(--green)';document.getElementById('emsg_'+id).textContent='✅ Recommended to Trainer.';logAudit('Enrollment recommended',rec.agent+' → '+topicId,'data');refreshBell();}
window.evRecommend=evRecommend;
function renderFraudDash(){const ia=loadInteractions();const flagged=ia.filter(r=>(r.fraudScore||0)>0);document.getElementById('faKpis').innerHTML=[['Total Interactions',ia.length],['Flagged',flagged.length],['High-Risk (≥60)',ia.filter(r=>(r.fraudScore||0)>=60).length],['Session Flags',fraudFlags.length]].map(k=>'<div class="stat"><div class="n">'+k[1]+'</div><div class="l">'+k[0]+'</div></div>').join('');const types={};fraudFlags.forEach(f=>types[f.name]=(types[f.name]||0)+1);hbars('faTypes',Object.entries(types).map(([n,v])=>({n,v})).sort((a,b)=>b.v-a.v));const bySite={};ia.forEach(r=>{if(r.site&&(r.fraudScore||0)>0)bySite[r.site]=(bySite[r.site]||0)+1;});hbars('faSite',Object.entries(bySite).map(([n,v])=>({n,v})));const hi=ia.filter(r=>(r.fraudScore||0)>0).sort((a,b)=>(b.fraudScore||0)-(a.fraudScore||0)).slice(0,10);document.getElementById('faList').innerHTML=hi.length?hi.map(r=>'<div class="lib-card"><div class="lib-head"><div><b>'+esc(r.agent||'Unknown')+'</b><div class="lib-meta"><span>'+new Date(r.date).toLocaleDateString()+'</span><span style="color:var(--red)">🛡️ Risk '+r.fraudScore+'</span></div></div></div></div>').join(''):'<div class="note">No high-risk interactions recorded.</div>';}
function renderAdminDash(){const ia=loadInteractions();const users=loadUsers();const scored=ia.filter(r=>r.gapPct!=null);const avg=scored.length?Math.round(scored.reduce((a,r)=>a+r.gapPct,0)/scored.length):'—';document.getElementById('admKpis').innerHTML=[['Interactions',ia.length],['Users',users.length],['Agents',loadAgents().length],['Avg Quality',avg+(avg==='—'?'':'%')]].map(k=>'<div class="stat"><div class="n">'+k[1]+'</div><div class="l">'+k[0]+'</div></div>').join('');const modes={};ia.forEach(r=>modes[r.mode]=(modes[r.mode]||0)+1);hbars('admMode',Object.entries(modes).map(([n,v])=>({n:n.slice(0,18),v})));const bySite={};scored.forEach(r=>{if(r.site){if(!bySite[r.site])bySite[r.site]={s:0,n:0};bySite[r.site].s+=r.gapPct;bySite[r.site].n++;}});hbars('admSite',Object.entries(bySite).map(([n,o])=>({n,v:Math.round(o.s/o.n)})).sort((a,b)=>b.v-a.v));const roles={};users.forEach(u=>roles[ROLES[u.role].label]=(roles[ROLES[u.role].label]||0)+1);hbars('admRoles',Object.entries(roles).map(([n,v])=>({n,v})));document.getElementById('admHealth').innerHTML='<div class="sum-line"><b>AI Script</b><span>'+(aiCfg.provider==='claude'?'🟠 Claude ('+aiCfg.claudeModel+')':aiCfg.provider==='copilot'?'🔵 Copilot':'🟢 KB')+((aiCfg.provider==='claude'&&aiCfg.claudeKey)||(aiCfg.provider==='copilot'&&aiCfg.copKey)?' · key set':' · no key')+'</span></div><div class="sum-line"><b>Roles</b><span>6 (Agent·Evaluator·Supervisor·Trainer·Fraud·Admin)</span></div><div class="sum-line"><b>Insights</b><span>📈 word cloud · gap analysis · recommendations</span></div><div class="sum-line"><b>KB Bot</b><span>FeeBe 🤖 active</span></div><div class="sum-line"><b>Languages</b><span>EN·TL·Ceb·Hil·Ilo·War·Taglish·JP·HK</span></div><div class="sum-line"><b>Audit events</b><span>'+loadAudit().length+'</span></div><div style="margin-top:12px"><button class="btn ghost" onclick="showView(\'insights\')">📈 Insights</button> <button class="btn ghost" onclick="showView(\'access\')">🔐 Access</button> <button class="btn ghost" onclick="showView(\'audit\')">🧾 Audit</button></div>';}
function renderSupervisorDash(){const evs=loadEvals();const pend=evs.filter(e=>e.status==='sent');const en=loadEnroll();document.getElementById('svKpis').innerHTML=[['Inbox',evs.length],['Awaiting feedback',pend.length],['QA notified',evs.filter(e=>e.status==='qa_notified').length],['Enroll recs',en.length]].map(k=>'<div class="stat"><div class="n">'+k[1]+'</div><div class="l">'+k[0]+'</div></div>').join('');document.getElementById('svPending').innerHTML=pend.length?pend.slice(0,8).map(e=>'<div class="hbar-row"><span class="name">'+esc(e.agent)+'</span><div class="track"><span style="width:'+Math.max(12,e.score)+'%;background:'+heatColor(e.score)+'">'+e.score+'%</span></div></div>').join(''):'<div class="note">No pending evaluations 🎉</div>';document.getElementById('svEnroll').innerHTML=en.length?en.slice(0,8).map(x=>'<div class="sum-line"><b>'+esc(x.agent)+'</b><span>'+esc((topicById(x.topicId)||{}).name||x.topicId)+' · '+x.status+'</span></div>').join(''):'<div class="note">No recommendations yet.</div>';const sel=document.getElementById('coachAgent');if(sel){const ags=loadUsers().filter(u=>u.role==='agent'&&u.status==='active');sel.innerHTML=ags.map(a=>'<option value="'+a.user+'">'+esc(a.name)+(a.emp?' · '+a.emp:'')+'</option>').join('')+'<option value="__name">— type a name —</option>';}renderCoachHist();}
function coachPreview(){const p=document.getElementById('coachPrev');p.classList.remove('hidden');p.innerHTML='<div class="lbl">PREVIEW</div>'+mdToHtml(document.getElementById('coachMd').value);}
window.coachPreview=coachPreview;
function sendCoach(){const sel=document.getElementById('coachAgent');let toUser=sel.value,toName='';if(toUser==='__name'){toName=prompt('Agent full name:')||'';toUser='';const u=loadUsers().find(x=>x.name.toLowerCase()===toName.toLowerCase());if(u)toUser=u.user;}else{const u=loadUsers().find(x=>x.user===toUser);toName=u?u.name:'';}const topic=document.getElementById('coachTopic').value.trim();const body=document.getElementById('coachMd').value.trim();const msg=document.getElementById('coachMsg');if((!toUser&&!toName)||!body){msg.style.color='var(--red)';msg.textContent='⚠️ Pick an agent and write a note.';return;}const c=loadCoach();c.unshift({id:'CN-'+Date.now(),toUser,toName,topic,body,from:currentUser.user,fromName:currentUser.name,ts:new Date().toISOString(),ack:false});saveCoach(c);notify('agent',toUser,'📝 New coaching note from '+currentUser.name+(topic?' · '+topic:''),'coach');msg.style.color='var(--green)';msg.textContent='✅ Sent to '+(toName||toUser)+'.';document.getElementById('coachMd').value='';document.getElementById('coachTopic').value='';renderCoachHist();logAudit('Coaching note sent','to '+(toName||toUser),'data');}
window.sendCoach=sendCoach;
function renderCoachHist(){const el=document.getElementById('coachHist');if(!el)return;const mine=loadCoach().filter(x=>x.from===currentUser.user||currentUser.role==='admin');el.innerHTML=mine.length?mine.slice(0,30).map(x=>'<div class="lib-card"><div class="lib-head"><div><b>➡️ '+esc(x.toName||x.toUser)+'</b>'+(x.topic?' <span class="tag">'+esc(x.topic)+'</span>':'')+(x.ack?' <span class="tag" style="background:#dcfce7;color:#166534">acknowledged</span>':' <span class="tag y">sent</span>')+'<div class="lib-meta"><span>'+new Date(x.ts).toLocaleString()+'</span></div><div class="script-card" style="margin-top:6px">'+mdToHtml(x.body)+'</div></div></div></div>').join(''):'<div class="note">No coaching notes sent yet.</div>';}
function renderSupQueue(){const list=document.getElementById('supQueueList');if(!list)return;const f=(document.getElementById('supFilter')||{}).value||'all';const evs=loadEvals().filter(e=>f==='all'||e.status===f);document.getElementById('supQueueEmpty').style.display=evs.length?'none':'block';list.innerHTML=evs.map(e=>{const topic=topicById(e.topicId);const st=e.status==='sent'?'<span class="tag y">Awaiting feedback</span>':e.status==='feedback_done'?'<span class="tag">Feedback done</span>':'<span class="tag" style="background:#dcfce7;color:#166534">QA notified</span>';const rec=loadInteractions().find(x=>x.id===e.interactionId);return '<div class="lib-card"><div class="lib-head"><div><b>'+esc(e.agent)+'</b> · QA '+e.score+'/100 '+st+'<div class="lib-meta"><span>from '+esc(e.from)+'</span>'+(e.site?'<span>🏢 '+esc(e.site)+'</span>':'')+'<span>'+new Date(e.ts).toLocaleString()+'</span>'+(topic?'<span>🎓 rec: '+esc(topic.name)+'</span>':'')+'</div>'+(e.gaps&&e.gaps.length?'<div style="margin-top:6px">'+e.gaps.map(g=>'<span class="tag r">'+esc(g)+'</span>').join('')+'</div>':'')+(e.note?'<div class="script-card" style="margin-top:8px">'+mdToHtml(e.note)+'</div>':'')+(e.feedback?'<div class="ai-guide-box" style="margin-top:8px"><b>🧑‍✈️ Feedback:</b><br>'+mdToHtml(e.feedback)+'</div>':'')+'</div><div class="lib-actions"><button onclick="toggleReplay(\''+e.interactionId+'\')">👁 Call</button><button onclick="dmOpen(\''+esc(e.from)+'\')">💬 QA</button></div></div>'+(e.status!=='qa_notified'?'<div class="row" style="margin-top:10px"><input class="inp" id="fb_'+e.id+'" placeholder="Feedback (Markdown ok)…" style="flex:1" value="'+esc(e.feedback||'')+'"><button class="btn" onclick="supSaveFeedback(\''+e.id+'\')">💾 Save</button><button class="btn mag" onclick="supNotifyQA(\''+e.id+'\')">🔔 Notify QA</button></div>':'')+'<div class="replay" id="rp_'+e.interactionId+'">'+(rec?replayHTML(rec):'')+'</div></div>';}).join('');refreshBell();}
window.renderSupQueue=renderSupQueue;
function supSaveFeedback(evId){const evs=loadEvals();const e=evs.find(x=>x.id===evId);if(!e)return;e.feedback=(document.getElementById('fb_'+evId)||{}).value||'';if(e.status==='sent')e.status='feedback_done';saveEvals(evs);renderSupQueue();logAudit('Supervisor feedback saved','eval '+evId,'data');}
