function supNotifyQA(evId){const evs=loadEvals();const e=evs.find(x=>x.id===evId);if(!e)return;if(!e.feedback)e.feedback=(document.getElementById('fb_'+evId)||{}).value||'';e.status='qa_notified';saveEvals(evs);notify('evaluator',e.from,'✅ Supervisor feedback ready for '+e.agent+'. QA notified.','feedback');renderSupQueue();logAudit('QA notified','eval '+evId+' for '+e.agent,'data');}
window.supNotifyQA=supNotifyQA;
function renderTrainer(){const en=loadEnroll();const f=(document.getElementById('trEnrollFilter')||{}).value||'all';const topics=loadTopics();document.getElementById('trKpis').innerHTML=[['Enroll queue',en.length],['Pending',en.filter(x=>x.status==='pending').length],['Enrolled',en.filter(x=>x.status==='enrolled').length],['Topics',topics.length]].map(k=>'<div class="stat"><div class="n">'+k[1]+'</div><div class="l">'+k[0]+'</div></div>').join('');const list=en.filter(x=>f==='all'||x.status===f);document.getElementById('trEnrollList').innerHTML=list.length?list.map(x=>{const tp=topicById(x.topicId);return '<div class="lib-card"><div class="lib-head"><div><b>'+esc(x.agent)+'</b> → 🎓 '+esc((tp||{}).name||x.topicId)+'<div class="lib-meta"><span>by '+esc(x.by)+'</span><span>'+new Date(x.ts).toLocaleDateString()+'</span><span class="tag '+(x.status==='completed'?'':'y')+'" style="margin:0">'+x.status+'</span></div>'+(x.note?'<div class="script-card" style="margin-top:6px">'+mdToHtml(x.note)+'</div>':'')+'</div><div class="lib-actions">'+(tp?'<button onclick="trViewTopic(\''+tp.id+'\')">📖 Module</button>':'')+(x.status!=='enrolled'?'<button onclick="trSetStatus(\''+x.id+'\',\'enrolled\')">✅ Enroll</button>':'')+(x.status!=='completed'?'<button onclick="trSetStatus(\''+x.id+'\',\'completed\')">🏁 Complete</button>':'')+' <button onclick="dmOpen(\''+esc(x.by)+'\')">💬 QA</button></div></div></div>';}).join(''):'<div class="note">No enrollments in this filter.</div>';document.getElementById('trTopicList').innerHTML=topics.map(t=>'<div class="sum-line"><b>'+esc(t.name)+'</b><span><button class="btn ghost" style="padding:3px 8px;font-size:11px" onclick="trEditTopic(\''+t.id+'\')">✏️</button> <button class="btn ghost" style="padding:3px 8px;font-size:11px" onclick="trViewTopic(\''+t.id+'\')">👁</button></span></div>').join('');}
window.renderTrainer=renderTrainer;
function trSetStatus(id,st){const en=loadEnroll();const x=en.find(e=>e.id===id);if(x){x.status=st;saveEnroll(en);renderTrainer();logAudit('Enrollment '+st,x.agent,'data');if(st==='completed')notify('evaluator',x.by,'🏁 '+x.agent+' completed: '+((topicById(x.topicId)||{}).name||x.topicId),'training');}}
