function trSaveTopic(){const name=document.getElementById('trTopicName').value.trim();const md=document.getElementById('trTopicMd').value;if(!name){alert('Topic name required.');return;}const topics=loadTopics();const editId=document.getElementById('trTopicName').dataset.editId;if(editId){const t=topics.find(x=>x.id===editId);if(t){t.name=name;t.md=md;}delete document.getElementById('trTopicName').dataset.editId;}else topics.push({id:'t'+Date.now(),name,md});saveTopics(topics);document.getElementById('trTopicName').value='';document.getElementById('trTopicMd').value='';renderTrainer();logAudit('Training topic saved',name,'config');}
