function feebeSearch(q){q=(q||'').toLowerCase();const words=q.split(/\W+/).filter(w=>w.length>2);const hits=[];getKB().forEach(m=>{const hay=((m.q||'')+' '+(m.a||'')+' '+((m.k||[]).join(' '))).toLowerCase();let s=0;words.forEach(w=>{if(hay.includes(w))s++;});(m.k||[]).forEach(k=>{if(q.includes(k))s+=2;});if(s>0)hits.push({s,title:m.q,body:m.a,link:m.link||'',src:'KB'});});loadKBAssets().forEach(a=>{if(!a.content)return;const hay=(a.name+' '+a.content).toLowerCase();let s=0;words.forEach(w=>{if(hay.includes(w))s++;});if(s>0){const w0=words.find(w=>a.content.toLowerCase().includes(w))||'';const idx=a.content.toLowerCase().indexOf(w0);hits.push({s,title:a.name,body:a.content.slice(Math.max(0,idx-60),idx+240).trim()+'…',link:a.url||'',src:a.kind==='web'?'Website':'File'});}});hits.sort((x,y)=>y.s-x.s);return hits.slice(0,4);}
function feebeMsg(who,html){const body=document.getElementById('kbbotBody');if(!body)return null;const m=document.createElement('div');m.className='msg '+(who==='bot'?'ai':'cust');m.style.maxWidth='92%';m.innerHTML='<div class="who">'+(who==='bot'?'🤖 FeeBe':'You')+'</div><span class="txt">'+html+'</span>';body.appendChild(m);body.scrollTop=body.scrollHeight;return m;}
async function botAnswer(q){feebeMsg('user',esc(q));const hits=feebeSearch(q);let base;if(hits.length){base=hits.map(h=>'<div style="margin-bottom:8px"><b>'+esc(h.title)+'</b> <span class="tag" style="margin:0">'+h.src+'</span><br>'+esc(h.body)+(h.link?'<br><a class="kb-link" href="'+h.link+'" target="_blank">🔗 Reference</a>':'')+'</div>').join('');}else{base='I couldn\u2019t find that in the Knowledge Base yet. Try different keywords, or add it under 📚 Knowledge Base (files, websites, or a trainer module).';}const useClaude=(aiCfg.provider==='claude'&&aiCfg.claudeKey);const el=feebeMsg('bot',base+(useClaude?'<div class="note"><span class="spin"></span> Refining with Claude…</div>':''));if(useClaude&&el){try{const ctx=hits.map(h=>'• '+h.title+': '+h.body).join('\n')||'(no KB match)';const sys="You are FeeBe, the Inspiro/Infocom knowledge-base assistant. Answer ONLY from the provided KB context; if missing, say so and suggest what to add. Concise. Reply in the user's language (English/Tagalog/Cebuano/Hiligaynon/Ilokano/Waray).";const ans=await callClaude('KB context:\n'+ctx+'\n\nQuestion: '+q,sys);el.querySelector('.txt').innerHTML=esc(ans).replace(/\n/g,'<br>')+'<div class="note" style="margin-top:6px">📚 grounded in KB · <span class="ai-badge claude">Claude</span></div>';}catch(e){el.querySelector('.txt').innerHTML=base+'<div class="note">(Claude unavailable — showing KB matches. '+esc(e.message||'')+')</div>';}}try{logAudit('FeeBe query',q.slice(0,80),'data');}catch(e){}}
window.botAnswer=botAnswer;
window.botSend=function(){const inp=document.getElementById('kbbotInput');if(!inp)return;const q=(inp.value||'').trim();if(!q)return;inp.value='';botAnswer(q);};
